-- Penandaan miskonsepsi pada pengecoh soal Bahasa Indonesia SMA.
-- Sumber: supabase/seed/tka-bahasa-indonesia-sma-miskonsepsi.map.json
-- Dihasilkan oleh scripts/generate-misconception-tags.mjs. Aman dijalankan ulang.
--
-- 100 definisi miskonsepsi, 129 soal, 422 pengecoh dan pernyataan ditandai.
begin;

insert into public.misconceptions (id, label, description, insight) values
  ('mis-bi-kosakata-001', 'Menyimpulkan hanya dari satu kata', 'Menentukan latar, karakter, atau fenomena dari satu kata tanpa memeriksa kata-kata lain di sekitarnya.', 'Gunakan beberapa kata yang muncul bersama, karena satu kata saja dapat menunjuk banyak keadaan.'),
  ('mis-bi-kosakata-002', 'Mencampur latar tempat dengan suasana', 'Menganggap kata yang menunjukkan suasana sekaligus menunjukkan lokasi tertentu.', 'Bedakan petunjuk tempat, petunjuk waktu, dan petunjuk suasana; ketiganya sering muncul dalam satu paragraf.'),
  ('mis-bi-kosakata-003', 'Menyimpulkan watak tokoh dari kesan umum', 'Memilih sifat tokoh dari kesan sekilas, bukan dari pola ucapan dan tindakannya.', 'Cari bukti berupa pilihan kata, tanggapan, dan tindakan tokoh, bukan kesan sekilas.'),
  ('mis-bi-kosakata-004', 'Menganggap semua istilah teknologi menunjuk hal yang sama', 'Menyamakan seluruh kosakata digital sebagai penanda satu fenomena yang sama.', 'Bedakan istilah yang menamai proses, istilah yang menamai risiko, dan istilah yang menamai perilaku pengguna.'),
  ('mis-bi-kosakata-005', 'Tidak mengenali bidang dari kelompok istilahnya', 'Tidak menangkap bidang pembicaraan yang ditandai oleh sekelompok istilah khas.', 'Kumpulkan istilah yang berasal dari satu bidang; kelompok itulah yang menunjukkan pokok pembicaraannya.'),
  ('mis-bi-kosakata-006', 'Menukar penyebab dengan keadaan yang tampak', 'Memilih penyebab ketika yang ditanyakan keadaan yang tampak, atau sebaliknya.', 'Pisahkan apa yang terjadi, apa penyebabnya, dan apa akibatnya sebelum memilih jawaban.'),
  ('mis-bi-kosakata-007', 'Memilih jawaban dari pengetahuan di luar teks', 'Memilih hal yang lazim terjadi di kehidupan nyata meskipun kosakata teks tidak menopangnya.', 'Utamakan kata-kata yang benar-benar dipakai teks, bukan hal yang biasanya terjadi di luar teks.'),
  ('mis-bi-kosakata-008', 'Melewatkan nuansa cara tokoh berbicara', 'Tidak menangkap sikap tokoh dari pilihan kata, larangan, keraguan, atau jeda dalam ujarannya.', 'Perhatikan cara sesuatu dikatakan, bukan hanya isi ucapannya secara harfiah.'),
  ('mis-bi-kosakata-009', 'Menganggap istilah kebencanaan sebagai penunjuk tempat', 'Menyamakan kosakata kebencanaan atau musim dengan lokasi maupun acara tertentu.', 'Istilah kebencanaan menunjukkan keadaan yang sedang berlangsung, belum tentu lokasi atau kegiatan tertentu.'),
  ('mis-bi-kosakata-010', 'Menganggap satu tindakan sebagai sifat tetap', 'Menganggap satu tindakan sesaat cukup membuktikan watak tokoh yang tetap.', 'Watak disimpulkan dari pola tindakan yang berulang, bukan dari satu kejadian saja.'),
  ('mis-bi-hubungan-001', 'Menganggap urutan waktu sebagai sebab-akibat', 'Menganggap bagian yang muncul lebih dahulu otomatis menjadi penyebab bagian sesudahnya.', 'Urutan waktu belum tentu hubungan sebab-akibat. Periksa apakah bagian pertama benar-benar menghasilkan bagian berikutnya.'),
  ('mis-bi-hubungan-002', 'Menganggap contoh sebagai gagasan baru', 'Membaca contoh atau ilustrasi sebagai topik yang terpisah dari gagasan sebelumnya.', 'Periksa lebih dahulu apakah bagian kedua hanya mengonkretkan gagasan sebelumnya, bukan menambah topik baru.'),
  ('mis-bi-hubungan-003', 'Menganggap pertentangan berarti pembatalan seluruhnya', 'Membaca kalimat atau paragraf yang bertentangan sebagai pembatalan seluruh isi bagian sebelumnya.', 'Pertentangan dapat membatasi atau memberi syarat, tidak selalu meniadakan seluruh pernyataan sebelumnya.'),
  ('mis-bi-hubungan-004', 'Keliru menentukan yang dirujuk kata ganti', 'Salah menentukan unsur yang dirujuk kata ini, itu, tersebut, ia, atau kata ganti lain.', 'Kembalikan kata rujukan ke kalimat sebelumnya, lalu uji apakah maknanya masih runtut.'),
  ('mis-bi-hubungan-005', 'Menukar akibat dengan tujuan', 'Membaca konsekuensi sebagai tujuan, atau sebaliknya.', 'Bedakan hasil yang terjadi dari sasaran yang hendak dicapai; keduanya ditandai kata penghubung yang berbeda.'),
  ('mis-bi-hubungan-006', 'Menganggap kalimat penjelas hanya mengulang', 'Menganggap kalimat atau paragraf penjelas tidak menambah makna apa pun.', 'Cari rincian, mekanisme, atau batasan yang ditambahkan bagian penjelas terhadap bagian sebelumnya.'),
  ('mis-bi-hubungan-007', 'Menyimpulkan sebab-akibat dari keterkaitan biasa', 'Menyimpulkan hubungan sebab-akibat padahal teks hanya menunjukkan dua hal yang berkaitan.', 'Hubungan sebab-akibat perlu penanda atau penjelasan mekanisme, tidak cukup dari dua hal yang muncul bersamaan.'),
  ('mis-bi-hubungan-008', 'Mengabaikan kata namun, meskipun, dan tetapi', 'Melewatkan penanda yang membatasi simpulan sehingga simpulannya menjadi terlalu jauh.', 'Kata namun, meskipun, dan tetapi membatasi simpulan; kedua sisi hubungannya harus tetap dibaca.'),
  ('mis-bi-hubungan-009', 'Membaca dua kalimat tanpa melihat isi paragrafnya', 'Menafsirkan hubungan dua bagian tanpa mempertimbangkan perannya di dalam paragraf.', 'Peran sebuah kalimat ditentukan oleh kedudukannya dalam paragraf, jadi paragrafnya perlu dibaca sebagai satu kesatuan.'),
  ('mis-bi-hubungan-010', 'Menganggap dua hal sejajar sebagai sebab dan akibat', 'Membaca dua aspek yang sederajat sebagai hubungan sebab dan akibat.', 'Periksa apakah kedua bagian sebenarnya merupakan cabang dari gagasan yang sama, bukan sebab dan akibat.'),
  ('mis-bi-inferensi-001', 'Menganggap kalimat pertama sebagai ide pokok', 'Mengambil kalimat pembuka sebagai ide pokok tanpa memeriksa keseluruhan isi teks.', 'Ide pokok harus menaungi seluruh informasi penting, jadi ujilah dengan bagian akhir teks juga.'),
  ('mis-bi-inferensi-002', 'Menganggap rincian yang menonjol sebagai ide pokok', 'Memilih rincian yang paling menarik atau paling mudah diingat sebagai simpulan utama.', 'Bedakan contoh, akibat, dan rincian dari gagasan yang menaungi seluruhnya.'),
  ('mis-bi-inferensi-003', 'Menyimpulkan lebih jauh daripada yang didukung teks', 'Menarik simpulan yang mungkin saja terjadi, tetapi tidak ditopang pernyataan dalam teks.', 'Simpulan perlu beberapa bukti yang searah di dalam teks, bukan hanya terasa masuk akal.'),
  ('mis-bi-inferensi-004', 'Menyimpulkan sifat tokoh dari satu tindakan', 'Menetapkan watak tokoh berdasarkan satu peristiwa tanpa melihat pola tindakannya.', 'Gabungkan ucapan, tindakan, dan tanggapan tokoh di beberapa bagian sebelum menyimpulkan wataknya.'),
  ('mis-bi-inferensi-005', 'Menganggap setiap peristiwa buruk sebagai konflik', 'Menganggap kejadian yang tidak menyenangkan otomatis menjadi konflik utama cerita.', 'Konflik adalah pertentangan tujuan, pilihan, kepentingan, atau perasaan, bukan sekadar kejadian buruk.'),
  ('mis-bi-inferensi-006', 'Menukar pergulatan batin dengan pertentangan dari luar', 'Keliru membedakan konflik di dalam diri tokoh dengan pertentangan antartokoh atau dengan keadaan.', 'Periksa sumber pertentangannya: dari dalam diri tokoh atau dari orang dan keadaan di luarnya.'),
  ('mis-bi-inferensi-007', 'Mengenali nilai hanya bila ditulis sebagai nasihat', 'Menganggap nilai hanya ada bila teks menyatakannya secara langsung sebagai petuah.', 'Nilai sering tersirat lewat keputusan tokoh dan akibat yang ditanggungnya, bukan lewat kalimat nasihat.'),
  ('mis-bi-inferensi-008', 'Menilai nilai hanya dari hasil akhirnya', 'Menilai baik atau buruknya tindakan hanya dari keberhasilan akhir, bukan dari proses dan pilihannya.', 'Perhatikan cara tokoh mengambil keputusan, bukan hanya berhasil atau gagalnya di akhir cerita.'),
  ('mis-bi-inferensi-009', 'Memilih rincian benar yang tidak mendukung simpulannya', 'Memilih informasi yang memang ada dalam teks, tetapi tidak berhubungan dengan simpulan yang ditanyakan.', 'Setiap bukti perlu diuji: apakah rincian itu benar-benar menopang gagasan yang sedang ditanyakan.'),
  ('mis-bi-inferensi-010', 'Menentukan latar dari pengetahuan di luar teks', 'Menetapkan waktu, tempat, atau suasana berdasarkan dugaan sendiri, bukan petunjuk dalam teks.', 'Gunakan petunjuk waktu, tempat, suasana, dan keadaan sosial yang benar-benar tersirat di dalam teks.'),
  ('mis-bi-kerangka-001', 'Menganggap contoh sebagai bagian utama kerangka', 'Memasukkan contoh atau rincian penjelas sebagai cabang utama kerangka.', 'Bedakan informasi inti dari contoh atau ilustrasi yang hanya memperjelasnya.'),
  ('mis-bi-kerangka-002', 'Menukar gagasan utama dengan rinciannya', 'Menempatkan rincian sebagai induk dan gagasan umum sebagai cabang.', 'Periksa tingkat keumuman setiap bagian: yang lebih umum menjadi induk, yang lebih khusus menjadi cabang.'),
  ('mis-bi-kerangka-003', 'Menyusun kerangka mengikuti urutan kalimatnya saja', 'Menganggap urutan kalimat dalam teks selalu sama dengan urutan logis informasinya.', 'Urutan kalimat tidak selalu sama dengan urutan logis; susunlah berdasarkan hubungan maknanya.'),
  ('mis-bi-kerangka-004', 'Membalik sebab dengan akibat', 'Menukar faktor pemicu dengan akibat yang ditimbulkannya.', 'Tanyakan mana yang secara logis terjadi lebih dahulu sebelum menyusun urutannya.'),
  ('mis-bi-kerangka-005', 'Mencampur langkah pengerjaan dengan tujuannya', 'Menyamakan langkah pelaksanaan dengan hasil yang hendak dicapai.', 'Pisahkan tindakan, tujuan yang hendak dicapai, dan dampak yang muncul.'),
  ('mis-bi-kerangka-006', 'Menambahkan tahap yang tidak ada di dalam teks', 'Memasukkan simpulan atau tahap yang terasa masuk akal tetapi tidak disebutkan teks.', 'Kerangka hanya memuat bagian yang benar-benar disebutkan teks, meskipun tahap lain terasa masuk akal.'),
  ('mis-bi-kerangka-007', 'Memilih bagan rapi yang mengubah hubungan isinya', 'Memilih bagan yang tampak teratur padahal hubungan antarinformasinya berubah.', 'Cocokkan setiap panah dan cabang bagan dengan hubungan yang dinyatakan teks.'),
  ('mis-bi-kerangka-008', 'Melewatkan tahap penghubung antara sebab dan akibat', 'Melewatkan gagasan perantara yang menghubungkan pemicu dengan dampaknya.', 'Cari tahap perantara yang menjembatani pemicu dengan hasilnya.'),
  ('mis-bi-kerangka-009', 'Menganggap yang terjadi lebih dahulu sebagai penyebab', 'Menganggap peristiwa yang muncul lebih awal pasti menjadi penyebab peristiwa berikutnya.', 'Bedakan urutan waktu dari hubungan sebab-akibat.'),
  ('mis-bi-kerangka-010', 'Menyusun kerangka yang terlalu rinci', 'Memilih kerangka yang penuh rincian sehingga tidak mewakili keseluruhan teks.', 'Kerangka perlu ringkas tetapi tetap mencakup struktur utama teksnya.'),
  ('mis-bi-bahasa-001', 'Menganggap bahasa formal selalu paling tepat', 'Menganggap kata atau susunan yang paling formal selalu paling sesuai.', 'Kesesuaian bahasa ditentukan tujuan tulisan, pembacanya, dan situasinya, bukan tingkat formalitasnya.'),
  ('mis-bi-bahasa-002', 'Menganggap kalimat yang lebih panjang lebih jelas', 'Menganggap penambahan kata otomatis membuat kalimat lebih jelas.', 'Kalimat efektif memuat informasi yang cukup tanpa kata berulang; menambah kata belum tentu menambah kejelasan.'),
  ('mis-bi-bahasa-003', 'Menganggap kata bersinonim selalu dapat ditukar', 'Menganggap kata yang bersinonim selalu memiliki nuansa dan konteks pemakaian yang sama.', 'Kata bersinonim dapat berbeda nuansa dan pasangan katanya, jadi periksa maknanya di dalam kalimat itu.'),
  ('mis-bi-bahasa-004', 'Menganggap istilah populer selalu tidak baku', 'Menganggap istilah yang populer selalu tidak layak dipakai dalam teks informatif.', 'Nilailah kebakuan dan kecocokan kata dengan pembacanya, bukan populer atau tidaknya kata itu.'),
  ('mis-bi-bahasa-005', 'Menganggap bahasa yang lebih teknis lebih berbobot', 'Menganggap semakin teknis bahasanya semakin baik untuk semua pembaca.', 'Istilah teknis hanya tepat bila sesuai kebutuhan dan pengetahuan pembacanya.'),
  ('mis-bi-bahasa-006', 'Menganggap kata ganti selalu merujuk kata terdekat', 'Menentukan rujukan kata ia, ini, atau tersebut hanya dari kata yang paling dekat.', 'Uji rujukan kata ganti dengan makna seluruh kalimat, bukan dengan jarak katanya.'),
  ('mis-bi-bahasa-007', 'Menganggap semua kata penghubung sama fungsinya', 'Menganggap kata penghubung dapat saling menggantikan tanpa mengubah makna.', 'Kenali hubungan yang dibawa setiap penghubung: sebab, akibat, pertentangan, syarat, atau tambahan.'),
  ('mis-bi-bahasa-008', 'Melewatkan kalimat yang dapat ditafsirkan ganda', 'Tidak menyadari susunan kalimat yang memungkinkan lebih dari satu tafsiran.', 'Pilih susunan yang membuat pelaku, objek, dan hubungannya jelas tanpa perlu ditebak pembaca.'),
  ('mis-bi-bahasa-009', 'Menganggap kata berlebihan lebih meyakinkan', 'Menganggap kata yang dramatis atau melebih-lebihkan selalu memperkuat pesan.', 'Nada tulisan perlu sepadan dengan tujuan dan buktinya; kata yang berlebihan justru mengurangi ketepatan.'),
  ('mis-bi-bahasa-010', 'Memotong informasi penting demi kalimat pendek', 'Menghapus unsur yang dibutuhkan pembaca hanya agar kalimatnya lebih pendek.', 'Hemat berarti membuang kata yang berulang, bukan membuang informasi yang dibutuhkan pembaca.'),
  ('mis-bi-evalinfo-001', 'Menganggap satu contoh sebagai bukti umum', 'Menganggap satu pengalaman atau satu kelompok kecil cukup membuktikan klaim yang berlaku umum.', 'Periksa seberapa luas cakupan buktinya sebelum menerima simpulan yang berlaku untuk semua.'),
  ('mis-bi-evalinfo-002', 'Menganggap informasi berangka pasti akurat', 'Menganggap informasi benar hanya karena memuat angka atau persentase.', 'Angka perlu diperiksa sumbernya, apa yang dihitung, dan bagaimana pengukurannya dilakukan.'),
  ('mis-bi-evalinfo-003', 'Menganggap dua hal yang muncul bersama sebagai sebab-akibat', 'Menyimpulkan hubungan sebab-akibat dari dua perubahan yang terjadi bersamaan.', 'Kemunculan bersama belum menjelaskan mekanismenya dan belum menyingkirkan faktor lain.'),
  ('mis-bi-evalinfo-004', 'Menganggap klaim cukup kuat karena sumbernya disebut', 'Menganggap penyebutan sumber tanpa rincian sudah membuat klaim memadai.', 'Periksa apakah sumber dan datanya benar-benar menopang klaim yang dibuat.'),
  ('mis-bi-evalinfo-005', 'Menganggap informasi yang berkaitan sudah cukup', 'Menganggap informasi yang berhubungan dengan topik sudah cukup untuk menarik simpulan.', 'Berkaitan dengan topik dan cukup untuk menyimpulkan adalah dua hal yang berbeda.'),
  ('mis-bi-evalinfo-006', 'Menganggap kata pasti dan terbukti sebagai bukti kuat', 'Menganggap kata pasti, terbukti, atau selalu menandakan klaim yang kuat.', 'Kekuatan klaim harus sebanding dengan buktinya, bukan dengan kata yang dipakai.'),
  ('mis-bi-evalinfo-007', 'Menerapkan temuan di luar batas datanya', 'Memberlakukan temuan pada orang, waktu, atau keadaan yang tidak tercakup datanya.', 'Perhatikan siapa yang diukur, kapan, di mana, dan bagaimana datanya diperoleh.'),
  ('mis-bi-evalinfo-008', 'Memilih rincian menarik yang tidak menolong penilaian', 'Memilih rincian yang menarik tetapi tidak membantu menilai klaim utamanya.', 'Utamakan informasi yang benar-benar mengubah kuat atau lemahnya penilaian.'),
  ('mis-bi-evalinfo-009', 'Menganggap klaim pasti salah bila buktinya belum lengkap', 'Menyimpulkan klaim salah hanya karena teks belum memberi bukti yang memadai.', 'Simpulan yang tepat kadang berupa belum dapat dipastikan, bukan langsung salah.'),
  ('mis-bi-evalinfo-010', 'Menganggap pengalaman pribadi setara pemeriksaan', 'Menganggap laporan atau pengalaman pribadi sama nilainya dengan pemeriksaan yang sistematis.', 'Bedakan cerita pengalaman sebagai ilustrasi dari bukti yang diperiksa secara sistematis.'),
  ('mis-bi-fiksi-001', 'Menganggap sebutan sifat lebih kuat daripada tindakan', 'Menganggap penyebutan sifat secara langsung selalu lebih kuat daripada tindakan atau dialog tokoh.', 'Bukti terkuat dalam cerita biasanya tindakan dan ucapan yang konkret, bukan penyebutan sifatnya.'),
  ('mis-bi-fiksi-002', 'Menganggap satu tindakan sebagai sifat tetap', 'Menjadikan satu tindakan sebagai watak tokoh yang tetap tanpa melihat keadaannya.', 'Periksa alasan, keadaan, dan pola tindakan tokoh sebelum menyimpulkan wataknya.'),
  ('mis-bi-fiksi-003', 'Menganggap ucapan tokoh sebagai fakta cerita', 'Menganggap semua ucapan tokoh merupakan fakta dalam cerita.', 'Ucapan tokoh dapat memuat pendapat, perasaan, atau kepentingannya sendiri, belum tentu fakta cerita.'),
  ('mis-bi-fiksi-004', 'Menganggap setiap nama tempat sudah membangun latar', 'Menganggap penyebutan tempat atau benda otomatis membangun latar cerita.', 'Detail latar baru berfungsi bila memberi rasa ruang, waktu, atau suasana kepada pembaca.'),
  ('mis-bi-fiksi-005', 'Menyamakan perasaan satu tokoh dengan suasana adegan', 'Menganggap emosi seorang tokoh sama dengan suasana keseluruhan adegan.', 'Suasana dibangun oleh keadaan lingkungan dan tanggapan beberapa unsur adegan, bukan perasaan satu tokoh.'),
  ('mis-bi-fiksi-006', 'Menganggap peristiwa yang berurutan pasti sebab-akibat', 'Menganggap dua peristiwa yang terjadi berurutan pasti berhubungan sebab-akibat.', 'Cari petunjuk yang benar-benar menghubungkan tindakan dengan akibatnya.'),
  ('mis-bi-fiksi-007', 'Memilih bagian paling dramatis sebagai bukti', 'Memilih bagian yang paling menegangkan meskipun tidak membuktikan hal yang ditanyakan.', 'Pilih bukti yang paling berhubungan dengan hal yang ditanyakan, bukan yang paling menegangkan.'),
  ('mis-bi-fiksi-008', 'Menambahkan motif yang tidak ada petunjuknya', 'Menambahkan alasan atau riwayat tokoh yang tidak memiliki petunjuk dalam teks.', 'Tafsiran perlu berhenti pada hal yang masih memiliki petunjuk di dalam teks.'),
  ('mis-bi-fiksi-009', 'Menganggap deskripsi yang lebih panjang lebih tepat', 'Menganggap bagian yang lebih panjang otomatis lebih kuat menggambarkan unsur cerita.', 'Ketepatan penggambaran ditentukan mutu dan kaitan detailnya, bukan panjangnya.'),
  ('mis-bi-fiksi-010', 'Hanya menerima yang dinyatakan langsung', 'Mengabaikan watak atau suasana yang dibangun secara tidak langsung.', 'Watak dan suasana sering dibangun tidak langsung lewat tindakan, dialog, dan pilihan detail.'),
  ('mis-bi-prediksi-001', 'Menebak dari kemungkinan umum, bukan petunjuk teks', 'Memilih kejadian yang mungkin terjadi di kehidupan nyata tetapi tidak disiapkan oleh teks.', 'Prediksi harus bertumpu pada petunjuk khusus di dalam teks, bukan pada hal yang biasanya terjadi.'),
  ('mis-bi-prediksi-002', 'Memilih kelanjutan yang paling dramatis', 'Memilih kelanjutan yang paling mengejutkan meskipun tidak menyambung dengan cerita.', 'Utamakan kesinambungan watak, konflik, dan arah teks, bukan kejutannya.'),
  ('mis-bi-prediksi-003', 'Memilih kelanjutan yang hanya mengulang', 'Memilih kelanjutan yang mengulang informasi tanpa mengembangkan uraian.', 'Kelanjutan yang baik bergerak dari informasi yang sudah dibangun menuju langkah berikutnya.'),
  ('mis-bi-prediksi-004', 'Mengabaikan perubahan yang sudah terjadi pada tokoh', 'Memprediksi tindakan tokoh dari keadaan awalnya dan melewatkan perkembangan yang telah terjadi.', 'Gunakan keadaan tokoh yang paling akhir sebelum bagian yang diprediksi.'),
  ('mis-bi-prediksi-005', 'Membalik arah uraian tanpa dasar', 'Memilih lanjutan yang berlawanan dengan pendirian teks tanpa penanda perubahan.', 'Pertahankan arah uraian teks kecuali teks sendiri memberi alasan untuk berbalik.'),
  ('mis-bi-prediksi-006', 'Memilih contoh baru yang tidak menyambung', 'Memilih contoh yang masih setema tetapi tidak mengembangkan gagasan sebelumnya.', 'Contoh harus menyambung gagasan yang sedang dikembangkan, bukan sekadar setema.'),
  ('mis-bi-prediksi-007', 'Memutus rantai sebab dan akibat', 'Memilih akibat yang tidak mengikuti sebab atau syarat yang sudah dijelaskan teks.', 'Periksa sebab, syarat, dan akibat yang sudah dijelaskan sebelum memilih kelanjutannya.'),
  ('mis-bi-prediksi-008', 'Memilih akhir yang menyelesaikan semuanya sekaligus', 'Memilih akhir yang menuntaskan seluruh masalah secara mendadak tanpa persiapan.', 'Akhir cerita perlu sepadan dengan konflik dan petunjuk yang tersedia, bukan tuntas mendadak.'),
  ('mis-bi-prediksi-009', 'Memprediksi dari satu detail yang menonjol', 'Menyusun prediksi hanya dari satu detail menarik dan mengabaikan keseluruhan teks.', 'Gabungkan beberapa petunjuk yang searah sebelum menentukan prediksi.'),
  ('mis-bi-prediksi-010', 'Memberi saran yang melampaui isi uraiannya', 'Memilih saran yang terdengar benar tetapi tidak diturunkan dari pembahasan teks.', 'Saran harus merupakan lanjutan langsung dari masalah yang sudah dibahas teks.'),
  ('mis-bi-relevansi-001', 'Menganggap dua hal relevan karena bendanya mirip', 'Menganggap dua keadaan relevan hanya karena benda, tempat, atau tokohnya serupa.', 'Cari kesamaan masalah, keputusan, atau prinsipnya, bukan kesamaan benda atau tempatnya.'),
  ('mis-bi-relevansi-002', 'Menganggap tema yang sama sudah berarti relevan', 'Menganggap keadaan yang bertema sama otomatis menerapkan gagasan yang sama.', 'Tema yang sama belum cukup; periksa apakah masalah dan tindakannya sejalan.'),
  ('mis-bi-relevansi-003', 'Mengubah tindakan yang tepat menjadi aturan mutlak', 'Menjadikan tindakan yang tepat pada satu keadaan sebagai aturan untuk semua keadaan.', 'Pertahankan syarat dan batas keadaan yang membuat tindakan itu tepat.'),
  ('mis-bi-relevansi-004', 'Menerapkan cara yang sama pada keadaan yang berbeda', 'Menerapkan penyelesaian dari teks meskipun keadaan penting pada situasi baru berbeda.', 'Nilai lebih dahulu apakah keadaan yang membuat tindakan itu tepat masih berlaku.'),
  ('mis-bi-relevansi-005', 'Menganggap penerapan harus sama persis', 'Menganggap sebuah tindakan baru relevan hanya bila sama persis dengan peristiwa dalam teks.', 'Relevansi dapat berupa prinsip yang sama meskipun tindakannya berbeda.'),
  ('mis-bi-relevansi-006', 'Menilai relevan atau tidak tanpa bukti dari teks', 'Menentukan relevansi berdasarkan pendapat sendiri tanpa menghubungkannya dengan teks.', 'Gunakan peristiwa dan alasan di dalam teks sebagai dasar penilaian.'),
  ('mis-bi-relevansi-007', 'Menganggap hasil yang sama berarti caranya sama', 'Menganggap hasil yang serupa membuktikan kedua keadaan memakai prinsip yang sama.', 'Periksa proses pengambilan keputusannya, bukan hanya hasil akhirnya.'),
  ('mis-bi-relevansi-008', 'Menganggap niat baik membuat tindakan selalu tepat', 'Menganggap tindakan sudah tepat semata-mata karena tujuannya baik.', 'Tujuan yang baik masih perlu dinilai bersama caranya, risikonya, dan keadaannya.'),
  ('mis-bi-relevansi-009', 'Terpaku pada satu detail sehingga prinsipnya terlewat', 'Terpusat pada satu detail sehingga inti peristiwanya tidak terbaca.', 'Tentukan lebih dahulu inti keputusan atau peristiwanya, baru cari padanannya.'),
  ('mis-bi-relevansi-010', 'Memaksakan hubungan antara dua keadaan', 'Menghubungkan teks dengan keadaan baru melalui dugaan yang tidak tersedia dalam teks.', 'Jangan menambah syarat baru hanya agar dua keadaan tampak berhubungan.'),
  ('mis-bi-emosi-001', 'Menyamakan perasaan tokoh dengan perasaan pembaca', 'Menyamakan perasaan tokoh dengan perasaan yang dibangun teks pada pembacanya.', 'Bedakan keadaan perasaan tokoh dari efek yang dibangun teks pada pembacanya.'),
  ('mis-bi-emosi-002', 'Menentukan suasana hanya dari satu kata', 'Menentukan perasaan yang dibangun teks hanya dari satu kata tanpa melihat perkembangannya.', 'Gunakan rangkaian gambaran, tindakan, dialog, dan perubahan keadaan, bukan satu kata saja.'),
  ('mis-bi-emosi-003', 'Menganggap hanya boleh ada satu perasaan', 'Menganggap sebuah teks hanya dapat membangun satu perasaan tanpa campuran atau pergeseran.', 'Sebuah teks dapat membangun perasaan campuran atau bergeser; pilih yang paling didukung buktinya.'),
  ('mis-bi-emosi-004', 'Menganggap peristiwa sedih selalu berujung putus asa', 'Menganggap peristiwa kehilangan atau kegagalan selalu menghasilkan keputusasaan.', 'Perhatikan apakah teks juga membangun penerimaan, harapan, kehangatan, atau perenungan.'),
  ('mis-bi-emosi-005', 'Memilih bagian paling mencolok sebagai bukti perasaan', 'Memilih detail yang paling mencolok meskipun bukan yang membangun perasaan yang ditanyakan.', 'Pilih bagian yang paling langsung membangun perasaan yang ditanyakan, bukan yang paling mencolok.'),
  ('mis-bi-emosi-006', 'Menganggap akhir cerita menghapus ketegangan sebelumnya', 'Menganggap penyelesaian konflik membuat ketegangan sebelumnya tidak lagi berarti.', 'Perasaan pembaca dapat berubah; telusuri bagian sebelum dan sesudah titik baliknya.'),
  ('mis-bi-emosi-007', 'Menentukan perasaan tanpa bukti dari teks', 'Menentukan perasaan hanya dari pengalaman atau pendapat sendiri tanpa mengaitkannya dengan teks.', 'Penilaian perasaan tetap perlu menunjuk bagian teks yang menjadi dasarnya.'),
  ('mis-bi-emosi-008', 'Menyamakan lega, tenang, dan gembira', 'Menyamakan harapan, lega, tenang, dan gembira sebagai perasaan yang sama.', 'Perhatikan nuansanya: harapan, lega, tenang, dan gembira dibangun oleh keadaan yang berbeda.'),
  ('mis-bi-emosi-009', 'Membaca dialog drama secara harfiah', 'Mengabaikan jeda, tindakan panggung, dan keadaan ketika menilai drama.', 'Dalam drama, perasaan dibangun oleh dialog sekaligus tindakan, jeda, dan keadaan panggungnya.'),
  ('mis-bi-emosi-010', 'Menganggap gambaran suasana hanya hiasan', 'Menganggap gambaran yang menyentuh indera tidak berperan membangun perasaan.', 'Gambaran yang menyentuh indera membentuk kedekatan, kesunyian, kecemasan, atau kehangatan.')
on conflict (id) do update set
  label = excluded.label,
  description = excluded.description,
  insight = excluded.insight;

update public.questions set options = '[{"key":"A","text":"<p>penyesuaian kegiatan agar paparan panas yang sudah terjadi lebih mudah dihadapi</p>","misconceptionId":"mis-bi-serapan-006"},{"key":"B","text":"<p>pengurangan risiko panas melalui perubahan kondisi lingkungan yang menjadi sumber paparan</p>"},{"key":"C","text":"<p>pengukuran suhu berkala untuk membandingkan perubahan kondisi antarwilayah perkotaan</p>","misconceptionId":"mis-bi-serapan-005"},{"key":"D","text":"<p>pemindahan kegiatan dari kawasan padat menuju kawasan yang memiliki suhu lebih rendah</p>","misconceptionId":"mis-bi-serapan-004"},{"key":"E","text":"<p>pemetaan wilayah secara digital untuk menentukan kawasan yang memerlukan perhatian khusus</p>","misconceptionId":"mis-bi-serapan-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-001';
update public.questions set statements = '[{"id":"A","text":"<p>Kata <em>adaptasi</em> memperjelas tindakan warga menyesuaikan kegiatan terhadap kondisi suhu yang sudah meningkat.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-serapan-006"},{"id":"B","text":"<p>Kata <em>digital</em> pada <em>pemetaan digital</em> menunjukkan bahwa pemetaan dilakukan dengan sarana atau teknologi pengolahan informasi.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-serapan-005"},{"id":"C","text":"<p>Kata <em>evaluasi</em> digunakan untuk menamai tindakan fisik menambah ruang hijau agar suhu kota langsung turun.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-serapan-003"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>Penambahan ruang hijau merupakan bagian mitigasi karena diarahkan untuk mengurangi dampak panas perkotaan.</p>"},{"key":"B","text":"<p>Penggeseran kegiatan olahraga ke pagi hari merupakan adaptasi karena sekolah menyesuaikan aktivitas dengan suhu yang telah meningkat.</p>"},{"key":"C","text":"<p>Pemetaan digital berarti pemerintah tidak lagi memerlukan pengamatan kondisi nyata di setiap kawasan.</p>","misconceptionId":"mis-bi-serapan-004"},{"key":"D","text":"<p>Evaluasi data suhu dilakukan untuk menilai perubahan kondisi setelah berbagai tindakan dijalankan.</p>"},{"key":"E","text":"<p>Mitigasi dan adaptasi bermakna sama karena keduanya selalu berupa penanaman pohon.</p>","misconceptionId":"mis-bi-serapan-006"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>hasil akhir yang dibentuk sistem setelah mengolah masukan dari pengguna</p>","misconceptionId":"mis-bi-serapan-005"},{"key":"B","text":"<p>rujukan digital yang digunakan untuk memeriksa ketepatan keluaran sistem</p>","misconceptionId":"mis-bi-serapan-004"},{"key":"C","text":"<p>proses pemeriksaan ulang terhadap informasi yang dihasilkan oleh sistem</p>","misconceptionId":"mis-bi-serapan-005"},{"key":"D","text":"<p>perintah atau masukan yang diberikan pengguna untuk mengarahkan respons sistem</p>"},{"key":"E","text":"<p>kemampuan pengguna untuk menilai manfaat dan keterbatasan penggunaan sistem</p>","misconceptionId":"mis-bi-serapan-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>karena istilah itu menamai proses menyusun perintah agar keluaran sesuai kebutuhan pengguna</p>","misconceptionId":"mis-bi-serapan-005"},{"key":"B","text":"<p>karena istilah itu menamai proses menerima keluaran yang disajikan sistem dengan bahasa meyakinkan</p>","misconceptionId":"mis-bi-serapan-008"},{"key":"C","text":"<p>karena istilah itu menamai proses memeriksa keluaran dengan bukti atau sumber yang tepercaya</p>"},{"key":"D","text":"<p>karena istilah itu menamai proses membentuk keluaran baru berdasarkan pola yang dipelajari sistem</p>","misconceptionId":"mis-bi-serapan-005"},{"key":"E","text":"<p>karena istilah itu menamai proses mengganti sumber belajar dengan jawaban yang diberikan sistem</p>","misconceptionId":"mis-bi-serapan-004"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-005';
update public.questions set statements = '[{"id":"A","text":"<p>Kata <em>generatif</em> menunjukkan bahwa sistem dapat membentuk keluaran baru berdasarkan pola yang dipelajarinya.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-serapan-005"},{"id":"B","text":"<p><em>Literasi AI</em> dalam teks hanya berarti keterampilan menulis perintah agar sistem memberi jawaban dengan cepat.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-serapan-012"},{"id":"C","text":"<p><em>Verifikasi</em> berarti menerima keluaran AI sebagai benar selama bahasa yang digunakan terdengar meyakinkan.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-serapan-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>pengumpulan dana bersama untuk membayar tenaga yang memperbaiki rumah warga</p>","misconceptionId":"mis-bi-serapan-008"},{"key":"B","text":"<p>pertukaran tenaga antarwarga yang dicatat berdasarkan jumlah jam kerja masing-masing</p>","misconceptionId":"mis-bi-serapan-010"},{"key":"C","text":"<p>penyediaan makanan bersama sebagai balasan setelah pekerjaan perbaikan rumah selesai</p>","misconceptionId":"mis-bi-serapan-009"},{"key":"D","text":"<p>pertemuan warga untuk membagi biaya dan menentukan orang yang bertanggung jawab</p>","misconceptionId":"mis-bi-serapan-004"},{"key":"E","text":"<p>bantuan kerja bersama antarwarga tanpa hubungan upah atau utang bernilai tertentu</p>"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>Beberapa tetangga datang membawa cangkul, ember, tali, dan makanan.</p>"},{"key":"B","text":"<p>Mereka bekerja tanpa menghitung upah per orang.</p>"},{"key":"C","text":"<p>penghuni baru semula mengira warga akan mengadakan rapat untuk mengumpulkan uang.</p>","misconceptionId":"mis-bi-serapan-008"},{"key":"D","text":"<p>seorang warga menjelaskan bahwa sambatan merupakan kebiasaan saling membantu pekerjaan yang cukup berat dan sulit diselesaikan sendiri.</p>"},{"key":"E","text":"<p>Hujan semalam merobohkan sebagian dinding rumah pemilik rumah.</p>","misconceptionId":"mis-bi-serapan-011"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>ukuran tingkat kerusakan yang tampak pada bangunan di suatu wilayah</p>","misconceptionId":"mis-bi-serapan-008"},{"key":"B","text":"<p>ukuran kedalaman sumber gempa dari permukaan pada lokasi kejadian</p>","misconceptionId":"mis-bi-serapan-011"},{"key":"C","text":"<p>ukuran kekuatan gempa yang berkaitan dengan energi yang dilepaskan</p>"},{"key":"D","text":"<p>ukuran tingkat guncangan yang dirasakan masyarakat pada setiap lokasi</p>","misconceptionId":"mis-bi-serapan-008"},{"key":"E","text":"<p>ukuran kemungkinan munculnya tsunami setelah suatu gempa terjadi</p>","misconceptionId":"mis-bi-serapan-011"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Kata <em>evakuasi</em> digunakan untuk menamai tindakan memindahkan orang dari lokasi berisiko menuju tempat yang lebih aman.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-serapan-005"},{"id":"B","text":"<p>Kata <em>mitigasi</em> memiliki cakupan lebih luas daripada evakuasi karena mencakup berbagai upaya untuk mengurangi risiko bencana.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-serapan-012"},{"id":"C","text":"<p>Kata <em>magnitudo</em> dapat digunakan untuk memastikan bahwa setiap lokasi akan mengalami tingkat kerusakan yang sama.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-serapan-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-serapan-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>persaingan layanan AI dalam menghasilkan jawaban yang semakin cepat</p>","misconceptionId":"mis-bi-kosakata-004"},{"key":"B","text":"<p>perubahan cara pengguna menjaga privasi ketika berinteraksi dengan AI</p>"},{"key":"C","text":"<p>peralihan seluruh penyimpanan dokumen pribadi ke layanan berbasis AI</p>","misconceptionId":"mis-bi-kosakata-007"},{"key":"D","text":"<p>peningkatan kemampuan AI dalam mengenali identitas setiap penggunanya</p>","misconceptionId":"mis-bi-kosakata-004"},{"key":"E","text":"<p>kebiasaan pengguna membandingkan kualitas jawaban dari beberapa layanan AI</p>","misconceptionId":"mis-bi-kosakata-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-001';
update public.questions set statements = '[{"id":"A","text":"<p>Kosakata <em>anonimisasi</em> dan <em>data sensitif</em> menandai persoalan perlindungan identitas dan informasi pribadi.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kosakata-005"},{"id":"B","text":"<p>Kosakata <em>prompt</em> dan <em>unggahan</em> menunjukkan adanya interaksi pengguna dengan sistem digital.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kosakata-004"},{"id":"C","text":"<p>Kosakata <em>persetujuan</em> menunjukkan bahwa setiap data yang dimasukkan pasti milik pengguna sendiri.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-kosakata-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>menghapus identitas yang tidak relevan sebelum dokumen diunggah</p>"},{"key":"B","text":"<p>membatasi informasi yang dimasukkan ke dalam sebuah <em>prompt</em></p>"},{"key":"C","text":"<p>meminta sistem menghasilkan ringkasan dalam waktu yang lebih singkat</p>","misconceptionId":"mis-bi-kosakata-004"},{"key":"D","text":"<p>memeriksa kembali bahan sebelum dibagikan kepada layanan digital</p>"},{"key":"E","text":"<p>menggunakan satu ruang percakapan untuk menyelesaikan beberapa jenis tugas</p>","misconceptionId":"mis-bi-kosakata-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>malam perkemahan ketika warga berkumpul dan menyiapkan perlengkapan bersama</p>","misconceptionId":"mis-bi-kosakata-001"},{"key":"B","text":"<p>malam setelah gempa ketika warga bertahan di area terbuka yang lebih aman</p>"},{"key":"C","text":"<p>malam pemadaman listrik ketika warga menunggu perbaikan jaringan di lapangan</p>","misconceptionId":"mis-bi-kosakata-001"},{"key":"D","text":"<p>malam latihan evakuasi ketika warga mengikuti simulasi kebencanaan terjadwal</p>","misconceptionId":"mis-bi-kosakata-009"},{"key":"E","text":"<p>malam hujan lebat ketika warga menghindari genangan di sekitar permukiman</p>","misconceptionId":"mis-bi-kosakata-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>waspada karena memeriksa sumber sebelum mempercayai informasi yang beredar</p>"},{"key":"B","text":"<p>cemas karena menghindari semua informasi yang muncul setelah terjadi guncangan</p>","misconceptionId":"mis-bi-kosakata-008"},{"key":"C","text":"<p>ragu karena menunggu orang lain menentukan informasi mana yang boleh dibaca</p>","misconceptionId":"mis-bi-kosakata-003"},{"key":"D","text":"<p>keras karena melarang orang lain menggunakan telepon selama keadaan darurat</p>","misconceptionId":"mis-bi-kosakata-008"},{"key":"E","text":"<p>pasif karena memilih tetap berada di lapangan tanpa melakukan tindakan apa pun</p>","misconceptionId":"mis-bi-kosakata-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>melarang adiknya kembali mengambil barang ketika situasi belum aman</p>"},{"key":"B","text":"<p>membaca pesan mengenai magnitudo yang masuk melalui telepon genggam</p>","misconceptionId":"mis-bi-kosakata-010"},{"key":"C","text":"<p>mengurungkan niat pulang setelah melihat retakan di dekat pagar</p>"},{"key":"D","text":"<p>membantu tetangga lanjut usia berpindah ke tempat yang lebih lapang</p>"},{"key":"E","text":"<p>ingin mengambil buku dan pengisi daya yang tertinggal di rumah</p>","misconceptionId":"mis-bi-kosakata-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>kesulitan belajar karena bahan bacaan menggunakan terlalu banyak istilah baru</p>","misconceptionId":"mis-bi-kosakata-006"},{"key":"B","text":"<p>perubahan pola perhatian akibat kebiasaan berpindah cepat antarstimulus digital</p>"},{"key":"C","text":"<p>keterbatasan waktu belajar akibat banyaknya tugas yang harus diselesaikan bersamaan</p>","misconceptionId":"mis-bi-kosakata-007"},{"key":"D","text":"<p>penurunan minat membaca karena seluruh bahan belajar telah berpindah ke format video</p>","misconceptionId":"mis-bi-kosakata-006"},{"key":"E","text":"<p>kebutuhan menggunakan gawai karena informasi pelajaran hanya tersedia secara daring</p>","misconceptionId":"mis-bi-kosakata-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-007';
update public.questions set statements = '[{"id":"A","text":"<p>Ardi mulai reflektif karena mampu menyebut pemicu yang mengganggu perhatiannya.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kosakata-003"},{"id":"B","text":"<p>Ardi menunjukkan usaha mengendalikan kebiasaan dengan memindahkan telepon dari ruang belajar.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kosakata-010"},{"id":"C","text":"<p>Ardi telah memiliki fokus yang stabil karena tidak pernah lagi kehilangan perhatian setelah mengubah kebiasaan.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-kosakata-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>dehidrasi, indeks ultraviolet, paparan panas, dan aktivitas luar ruang</p>","misconceptionId":"mis-bi-kosakata-005"},{"key":"B","text":"<p>ruang hijau, aliran udara, kepadatan bangunan, dan jenis permukaan</p>"},{"key":"C","text":"<p>puncak kemarau, periode kering, hujan, dan dinamika atmosfer</p>","misconceptionId":"mis-bi-kosakata-005"},{"key":"D","text":"<p>rumput menguning, tanah mengeras, debu, dan kendaraan yang melintas</p>","misconceptionId":"mis-bi-kosakata-006"},{"key":"E","text":"<p>siang hari, malam hari, bayangan, dan pepohonan di sisi jalan</p>","misconceptionId":"mis-bi-kosakata-001"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p><em>Puncak kemarau</em> menunjukkan fase dominannya karakter musim kering, bukan jaminan tidak ada hujan.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kosakata-009"},{"id":"B","text":"<p><em>Kepadatan bangunan</em> dan <em>jenis permukaan</em> menjadi petunjuk adanya faktor lingkungan kota dalam pembahasan panas.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kosakata-005"},{"id":"C","text":"<p><em>Dinamika atmosfer</em> menunjukkan bahwa kemarau selalu berakhir ketika satu kejadian hujan muncul.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-kosakata-009"}]'::jsonb, updated_at = now() where id = 'tka-bi-kosakata-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>kalimat ketiga memberikan contoh tambahan dari kelancaran bahasa pada kalimat kedua</p>","misconceptionId":"mis-bi-hubungan-002"},{"key":"B","text":"<p>kalimat ketiga membatasi anggapan yang dapat muncul akibat keadaan pada kalimat kedua</p>"},{"key":"C","text":"<p>kalimat ketiga menunjukkan akibat langsung yang selalu ditimbulkan oleh kalimat kedua</p>","misconceptionId":"mis-bi-hubungan-001"},{"key":"D","text":"<p>kalimat ketiga mengulang kalimat kedua dengan istilah berbeda tanpa menambah batasan makna</p>","misconceptionId":"mis-bi-hubungan-006"},{"key":"E","text":"<p>kalimat ketiga menjelaskan tujuan penggunaan bahasa lancar sebagaimana disebut kalimat kedua</p>","misconceptionId":"mis-bi-hubungan-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-hubungan-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>paragraf kedua merinci bahwa kebutuhan verifikasi berbeda menurut jenis dan risiko tugas</p>"},{"key":"B","text":"<p>paragraf ketiga menjelaskan cara memprioritaskan bagian keluaran yang perlu diperiksa</p>"},{"key":"C","text":"<p>kedua paragraf membatalkan gagasan bahwa AI dapat menghasilkan bahasa yang lancar</p>","misconceptionId":"mis-bi-hubungan-003"},{"key":"D","text":"<p>kedua paragraf mengembangkan alasan mengapa keluaran yang meyakinkan tetap perlu dinilai</p>"},{"key":"E","text":"<p>paragraf ketiga menyatakan seluruh kata dalam keluaran harus diperiksa dengan tingkat yang sama</p>","misconceptionId":"mis-bi-hubungan-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-hubungan-auth-002';
