update public.questions set statements = '[{"id":"A","text":"<p>kemasan terlalu besar → penggunaan bahan dan ruang angkut meningkat</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kerangka-004"},{"id":"B","text":"<p>pengemasan berlapis → material yang perlu dikelola bertambah</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kerangka-008"},{"id":"C","text":"<p>penggunaan kembali kemasan → seluruh limbah kemasan langsung hilang</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-kerangka-006"}]'::jsonb, updated_at = now() where id = 'tka-bi-kerangka-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>kabar awal → tindakan → pemeriksaan sumber → perbandingan informasi</p>","misconceptionId":"mis-bi-kerangka-008"},{"key":"B","text":"<p>kabar awal → pemeriksaan sumber → perbandingan informasi → keputusan keselamatan</p>"},{"key":"C","text":"<p>perbandingan informasi → kabar awal → keputusan → pemeriksaan sumber</p>","misconceptionId":"mis-bi-kerangka-003"},{"key":"D","text":"<p>pemeriksaan sumber → keputusan → kabar awal → perbandingan informasi</p>","misconceptionId":"mis-bi-kerangka-003"},{"key":"E","text":"<p>keputusan keselamatan → kabar awal → pemeriksaan → perbandingan informasi</p>","misconceptionId":"mis-bi-kerangka-004"}]'::jsonb, updated_at = now() where id = 'tka-bi-kerangka-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>jalur laporan warga dan jalur foto keadaan sekitar</p>","misconceptionId":"mis-bi-kerangka-010"},{"key":"B","text":"<p>jalur pemeriksaan informasi dan jalur keputusan keselamatan</p>"},{"key":"C","text":"<p>jalur magnitudo gempa dan jalur kerusakan bangunan</p>","misconceptionId":"mis-bi-kerangka-009"},{"key":"D","text":"<p>jalur pesan berantai dan jalur kelompok rentan</p>","misconceptionId":"mis-bi-kerangka-001"},{"key":"E","text":"<p>jalur waktu kejadian dan jalur lokasi pusat gempa</p>","misconceptionId":"mis-bi-kerangka-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-kerangka-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>karakter permukaan seperti beton, aspal, dan material atap</p>"},{"key":"B","text":"<p>keberadaan vegetasi yang memberi bayangan dan evapotranspirasi</p>"},{"key":"C","text":"<p>bentuk lingkungan terbangun yang memengaruhi aliran udara</p>"},{"key":"D","text":"<p>waktu matahari terbenam pada setiap hari dalam satu tahun</p>","misconceptionId":"mis-bi-kerangka-001"},{"key":"E","text":"<p>jumlah orang yang berjalan kaki pada sisi jalan saat siang</p>","misconceptionId":"mis-bi-kerangka-006"}]'::jsonb, updated_at = now() where id = 'tka-bi-kerangka-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Karakter permukaan → penyerapan dan pelepasan panas.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kerangka-004"},{"id":"B","text":"<p>Vegetasi → bayangan dan evapotranspirasi → membantu mengurangi panas.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-kerangka-008"},{"id":"C","text":"<p>Bangunan rapat → aliran udara selalu meningkat → panas lebih cepat terlepas.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-kerangka-004"}]'::jsonb, updated_at = now() where id = 'tka-bi-kerangka-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>Pilihan katanya terlalu percakapan dan emotif untuk panduan yang ditujukan kepada siswa, guru, dan orang tua.</p>"},{"key":"B","text":"<p>Kalimat tersebut terlalu pendek sehingga tidak dapat digunakan dalam dokumen panduan resmi sekolah.</p>","misconceptionId":"mis-bi-bahasa-002"},{"key":"C","text":"<p>Semua kata serapan dan istilah tentang teknologi seharusnya dihilangkan dari panduan pendidikan.</p>","misconceptionId":"mis-bi-bahasa-004"},{"key":"D","text":"<p>Kata “AI” harus diganti dengan istilah yang lebih panjang agar peringatan terdengar lebih ilmiah.</p>","misconceptionId":"mis-bi-bahasa-005"},{"key":"E","text":"<p>Peringatan tentang ketidakakuratan tidak boleh dicantumkan karena dapat membuat pembaca ragu menggunakan teknologi.</p>","misconceptionId":"mis-bi-bahasa-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>kata “dapat” menyatakan kemungkinan tanpa menggeneralisasi bahwa seluruh keluaran AI selalu salah</p>"},{"key":"B","text":"<p>frasa “memeriksa keluaran AI” menjelaskan tindakan yang dapat dilakukan pengguna</p>"},{"key":"C","text":"<p>kata “akurat” membuat setiap informasi teknologi otomatis menjadi bahasa ilmiah</p>","misconceptionId":"mis-bi-bahasa-005"},{"key":"D","text":"<p>frasa “tidak sesuai dengan sumber” memperjelas salah satu dasar yang dapat digunakan untuk pemeriksaan</p>"},{"key":"E","text":"<p>kalimat menjadi tepat terutama karena menggunakan lebih banyak kata daripada draf sebelumnya</p>","misconceptionId":"mis-bi-bahasa-002"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>terdapat beberapa unsur bermakna tumpang tindih sehingga kalimat tidak hemat dan informasi utama kurang langsung</p>"},{"key":"B","text":"<p>kalimat tidak memiliki angka sehingga peserta tidak dapat mengetahui perubahan waktu kegiatan</p>","misconceptionId":"mis-bi-bahasa-002"},{"key":"C","text":"<p>kata “peserta” tidak baku sehingga harus diganti dengan kata yang berasal dari bahasa daerah</p>","misconceptionId":"mis-bi-bahasa-004"},{"key":"D","text":"<p>pengumuman harus selalu menggunakan kalimat pasif agar dianggap sesuai dengan komunikasi resmi</p>","misconceptionId":"mis-bi-bahasa-001"},{"key":"E","text":"<p>informasi perubahan jadwal tidak boleh ditempatkan dalam satu kalimat bersama waktu pelaksanaan</p>","misconceptionId":"mis-bi-bahasa-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-003';
update public.questions set statements = '[{"id":"A","text":"<p>Mengganti “seluruh para peserta” menjadi “seluruh peserta”.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-bahasa-002"},{"id":"B","text":"<p>Mengganti “sebelumnya awalnya akan dilaksanakan” menjadi “semula dijadwalkan”.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-bahasa-003"},{"id":"C","text":"<p>Menghapus seluruh keterangan waktu agar kalimat pengumuman menjadi lebih singkat.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-bahasa-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>Sebelum Mengunggah Dokumen, Periksa Data yang Ikut Terbawa</p>"},{"key":"B","text":"<p>Bahaya Mengerikan Internet yang Akan Menghancurkan Semua Data Pribadimu!</p>","misconceptionId":"mis-bi-bahasa-009"},{"key":"C","text":"<p>Jangan Pernah Mengunggah Dokumen Apa Pun ke Layanan Daring</p>","misconceptionId":"mis-bi-bahasa-009"},{"key":"D","text":"<p>Rahasia Besar Dunia Digital yang Tidak Ingin Diketahui Pengguna</p>","misconceptionId":"mis-bi-bahasa-009"},{"key":"E","text":"<p>Dokumen Digital: Sebuah Fenomena Superkompleks pada Era Teknologi Modern</p>","misconceptionId":"mis-bi-bahasa-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>kata “ceroboh” memberi nada menghakimi yang tidak diperlukan untuk menjelaskan langkah pencegahan</p>"},{"key":"B","text":"<p>kata “hancur” tidak tepat menggambarkan risiko pengungkapan atau penyebaran data pribadi</p>"},{"key":"C","text":"<p>frasa “dalam sedetik” memperkuat akurasi karena semua risiko digital terjadi dalam waktu yang sama</p>","misconceptionId":"mis-bi-bahasa-009"},{"key":"D","text":"<p>keseluruhan judul lebih menakut-nakuti daripada menjelaskan kebiasaan yang ingin dibangun</p>"},{"key":"E","text":"<p>judul tidak sesuai semata-mata karena menggunakan tanda seru, yang tidak pernah boleh dipakai dalam teks digital</p>","misconceptionId":"mis-bi-bahasa-001"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>Setelah memeriksa tanaman yang layu, koordinator menyerahkan catatan kepada guru.</p>"},{"key":"B","text":"<p>Koordinator menyerahkan catatan kepada guru setelah ia melakukan pemeriksaan tersebut.</p>","misconceptionId":"mis-bi-bahasa-008"},{"key":"C","text":"<p>Catatan diserahkan kepada guru olehnya setelah tanaman yang layu diperiksa olehnya.</p>","misconceptionId":"mis-bi-bahasa-002"},{"key":"D","text":"<p>Setelah pemeriksaan, ia menyerahkan catatan itu kepadanya untuk kemudian dibahas bersama.</p>","misconceptionId":"mis-bi-bahasa-006"},{"key":"E","text":"<p>Koordinator dan guru memeriksa catatan setelah ia menyerahkan tanaman yang layu tersebut.</p>","misconceptionId":"mis-bi-bahasa-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-007';
update public.questions set statements = '[{"id":"A","text":"<p>Koordinator memeriksa tanaman yang layu sebelum menyerahkan catatan kepada guru.</p>","correctCategoryKey":"jelas","misconceptionId":"mis-bi-bahasa-006"},{"id":"B","text":"<p>Catatan yang telah diperiksa koordinator kemudian diserahkan kepada guru pendamping.</p>","correctCategoryKey":"jelas","misconceptionId":"mis-bi-bahasa-006"},{"id":"C","text":"<p>Koordinator berbicara kepada guru setelah ia selesai memeriksa tanaman.</p>","correctCategoryKey":"tidak_jelas","misconceptionId":"mis-bi-bahasa-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Pengguna wajib melakukan epistemic verification terhadap stochastic output sebelum melakukan downstream utilization.</p>"},{"key":"B","text":"<p>Periksa kembali informasi penting sebelum menggunakan keluaran AI sebagai bahan tugas.</p>","misconceptionId":"mis-bi-bahasa-001"},{"key":"C","text":"<p>Bandingkan fakta dan rujukan dalam jawaban dengan sumber yang dapat diperiksa.</p>","misconceptionId":"mis-bi-bahasa-001"},{"key":"D","text":"<p>Gunakan AI sebagai alat bantu, tetapi tetap nilai apakah hasilnya sesuai dengan kebutuhan.</p>","misconceptionId":"mis-bi-bahasa-001"},{"key":"E","text":"<p>Hindari memasukkan data pribadi yang tidak diperlukan untuk menyelesaikan tugas.</p>","misconceptionId":"mis-bi-bahasa-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Menempatkan perubahan waktu pada kalimat pertama agar informasi utama segera terlihat.</p>","correctCategoryKey":"meningkatkan","misconceptionId":"mis-bi-bahasa-002"},{"id":"B","text":"<p>Menambahkan tanggal dan lokasi untuk membedakan kegiatan dari agenda lain pada minggu yang sama.</p>","correctCategoryKey":"meningkatkan","misconceptionId":"mis-bi-bahasa-010"},{"id":"C","text":"<p>Menambahkan frasa “perlu untuk diketahui dan perlu untuk diperhatikan” sebelum setiap informasi.</p>","correctCategoryKey":"tidak_meningkatkan","misconceptionId":"mis-bi-bahasa-002"}]'::jsonb, updated_at = now() where id = 'tka-bi-bahasa-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>Klaim terlalu luas karena data hanya membandingkan waktu draf awal pada kelompok kecil dan satu jenis tugas.</p>"},{"key":"B","text":"<p>Klaim akurat karena 18 menit lebih singkat daripada 31 menit sehingga AI selalu mempercepat semua tahap tugas.</p>","misconceptionId":"mis-bi-evalinfo-007"},{"key":"C","text":"<p>Klaim pasti salah karena setiap penggunaan AI selalu membutuhkan waktu pemeriksaan yang lebih lama daripada menulis sendiri.</p>","misconceptionId":"mis-bi-evalinfo-009"},{"key":"D","text":"<p>Klaim cukup kuat karena kedua kelompok berasal dari kelas yang sama sehingga hasilnya berlaku bagi seluruh siswa.</p>","misconceptionId":"mis-bi-evalinfo-001"},{"key":"E","text":"<p>Klaim tidak perlu dinilai lagi karena artikel sudah mencantumkan angka rata-rata dari kedua kelompok.</p>","misconceptionId":"mis-bi-evalinfo-002"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>waktu yang digunakan kelompok AI untuk memeriksa dan memperbaiki draf setelah hasil awal dibuat</p>"},{"key":"B","text":"<p>perbandingan kualitas hasil akhir kedua kelompok setelah seluruh proses pengerjaan selesai</p>"},{"key":"C","text":"<p>warna antarmuka aplikasi AI yang digunakan oleh siswa selama kegiatan berlangsung</p>","misconceptionId":"mis-bi-evalinfo-008"},{"key":"D","text":"<p>hasil pengujian pada jenis tugas atau kelompok peserta lain agar cakupan klaim dapat dinilai</p>"},{"key":"E","text":"<p>jumlah kata dalam nama setiap siswa yang mengikuti percobaan di kelas tersebut</p>","misconceptionId":"mis-bi-evalinfo-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-002';
update public.questions set statements = '[{"id":"A","text":"<p>Pada pengukuran yang dilakukan, permukaan di bawah naungan lebih sejuk daripada paving yang terkena matahari langsung.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-evalinfo-009"},{"id":"B","text":"<p>Data membuktikan penanaman pohon akan menurunkan suhu udara seluruh kawasan sekolah sedikitnya 5°C pada setiap kondisi.</p>","correctCategoryKey":"tidak_didukung","misconceptionId":"mis-bi-evalinfo-007"},{"id":"C","text":"<p>Untuk menilai dampak terhadap kawasan secara keseluruhan, cakupan pengukuran perlu diperluas.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-evalinfo-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>Pada titik dan waktu pengukuran, permukaan yang dinaungi pohon tercatat lebih sejuk daripada paving yang terkena matahari langsung.</p>"},{"key":"B","text":"<p>Pohon terbukti menurunkan suhu seluruh sekolah minimal 5°C karena semua titik teduh selalu lebih dingin selama penelitian.</p>","misconceptionId":"mis-bi-evalinfo-007"},{"key":"C","text":"<p>Naungan pohon merupakan satu-satunya faktor yang menentukan suhu kawasan sekolah pada siang maupun malam hari.</p>","misconceptionId":"mis-bi-evalinfo-003"},{"key":"D","text":"<p>Semua halaman sekolah akan memiliki suhu yang sama apabila jumlah pohon yang ditanam dibuat sama banyak.</p>","misconceptionId":"mis-bi-evalinfo-003"},{"key":"E","text":"<p>Pengukuran tiga hari sudah cukup untuk memastikan kondisi suhu sekolah pada setiap musim sepanjang tahun.</p>","misconceptionId":"mis-bi-evalinfo-001"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>Pesan tidak menyertakan sumber dan dasar yang dapat diverifikasi untuk memastikan waktu serta kekuatan gempa susulan.</p>"},{"key":"B","text":"<p>Pesan menggunakan media percakapan, sedangkan semua informasi yang dikirim melalui media tersebut pasti salah.</p>","misconceptionId":"mis-bi-evalinfo-009"},{"key":"C","text":"<p>Gempa susulan tidak pernah terjadi setelah gempa utama sehingga isi pesan bertentangan dengan kenyataan.</p>","misconceptionId":"mis-bi-evalinfo-009"},{"key":"D","text":"<p>Informasi menjadi tidak akurat hanya karena kalimatnya meminta penerima menyebarkannya kepada orang lain.</p>","misconceptionId":"mis-bi-evalinfo-008"},{"key":"E","text":"<p>Pesan tidak menyebut jumlah anggota grup yang telah membaca informasi sebelum pesan tersebut diteruskan.</p>","misconceptionId":"mis-bi-evalinfo-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>parameter kejadian yang telah dilaporkan melalui sumber informasi yang dapat diverifikasi</p>"},{"key":"B","text":"<p>kondisi bangunan atau lingkungan sekitar yang dapat memengaruhi tindakan keselamatan</p>"},{"key":"C","text":"<p>ramalan waktu gempa berikutnya yang dinyatakan pasti meskipun tidak disertai dasar</p>","misconceptionId":"mis-bi-evalinfo-006"},{"key":"D","text":"<p>pembaruan dan anjuran keselamatan dari kanal kebencanaan yang dapat diperiksa sumbernya</p>"},{"key":"E","text":"<p>jumlah orang yang telah meneruskan pesan tanpa sumber sebagai ukuran kebenaran informasi</p>","misconceptionId":"mis-bi-evalinfo-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>Persentase tersebut menggambarkan responden evaluasi, bukan seluruh peserta yang mendaftar dalam program.</p>"},{"key":"B","text":"<p>Persentase tidak boleh digunakan dalam laporan kegiatan karena selalu menyesatkan pembaca tentang hasil program.</p>","misconceptionId":"mis-bi-evalinfo-009"},{"key":"C","text":"<p>Program pasti gagal karena tidak semua peserta mengisi formulir evaluasi pada akhir kegiatan membaca.</p>","misconceptionId":"mis-bi-evalinfo-009"},{"key":"D","text":"<p>Angka 76% salah karena setiap program harus memperoleh respons sedikitnya 90% sebelum dapat dievaluasi.</p>","misconceptionId":"mis-bi-evalinfo-002"},{"key":"E","text":"<p>Peningkatan membaca tidak mungkin dinilai melalui laporan peserta sehingga seluruh jawaban harus diabaikan.</p>","misconceptionId":"mis-bi-evalinfo-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-007';
update public.questions set statements = '[{"id":"A","text":"<p>data kebiasaan membaca peserta beberapa waktu setelah tantangan selesai</p>","correctCategoryKey":"diperlukan","misconceptionId":"mis-bi-evalinfo-007"},{"id":"B","text":"<p>informasi mengenai perubahan kebiasaan peserta yang tidak mengisi evaluasi akhir</p>","correctCategoryKey":"diperlukan","misconceptionId":"mis-bi-evalinfo-007"},{"id":"C","text":"<p>warna sampul buku yang paling banyak dibaca selama program berlangsung</p>","correctCategoryKey":"tidak_diperlukan","misconceptionId":"mis-bi-evalinfo-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>desain warna poster yang digunakan untuk mengumumkan pendaftaran tantangan membaca</p>"},{"key":"B","text":"<p>frekuensi membaca peserta sebelum dan selama periode program berlangsung</p>","misconceptionId":"mis-bi-evalinfo-005"},{"key":"C","text":"<p>proporsi peserta yang mengikuti evaluasi dibandingkan seluruh pendaftar program</p>","misconceptionId":"mis-bi-evalinfo-007"},{"key":"D","text":"<p>perubahan frekuensi membaca beberapa minggu setelah program berakhir</p>","misconceptionId":"mis-bi-evalinfo-007"},{"key":"E","text":"<p>cara pertanyaan evaluasi dirumuskan dan bagaimana jawaban peserta dikumpulkan</p>","misconceptionId":"mis-bi-evalinfo-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Dalam percobaan tersebut, kelompok yang memakai AI memiliki rata-rata waktu pembuatan draf awal lebih singkat.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-evalinfo-009"},{"id":"B","text":"<p>Data yang tersedia belum cukup untuk menyatakan bahwa seluruh proses pengerjaan semua jenis tugas menjadi lebih cepat.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-evalinfo-007"},{"id":"C","text":"<p>Karena terdapat selisih rata-rata waktu, AI telah terbukti meningkatkan kualitas hasil akhir seluruh siswa.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-evalinfo-003"}]'::jsonb, updated_at = now() where id = 'tka-bi-evalinfo-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>Ia membuka kembali foto catatan, membandingkannya dengan berkas, memperbaiki angka, lalu meminta Dimas memeriksa ulang.</p>"},{"key":"B","text":"<p>Nara menatap layar laptop ketika waktu pengiriman berkas tinggal lima menit lagi.</p>","misconceptionId":"mis-bi-fiksi-007"},{"key":"C","text":"<p>Dimas mengembuskan napas setelah mengatakan bahwa waktu yang tersisa hanya tiga menit.</p>","misconceptionId":"mis-bi-fiksi-003"},{"key":"D","text":"<p>Jam pada layar menunjukkan satu menit sebelum batas waktu ketika berkas akhirnya terkirim.</p>","misconceptionId":"mis-bi-fiksi-007"},{"key":"E","text":"<p>Nara baru bersandar setelah notifikasi pengiriman berkas muncul pada layar laptop.</p>","misconceptionId":"mis-bi-fiksi-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>Nara membuka foto catatan untuk membandingkan angka dengan berkas.</p>"},{"key":"B","text":"<p>Nara mengatakan bahwa waktu yang tersisa masih cukup untuk memastikan.</p>"},{"key":"C","text":"<p>Dimas sudah meletakkan jarinya di atas tombol kirim.</p>","misconceptionId":"mis-bi-fiksi-003"},{"key":"D","text":"<p>Nara meminta Dimas memeriksa kembali berkas setelah ia memperbaiki angka.</p>"},{"key":"E","text":"<p>Notifikasi pengiriman muncul satu menit sebelum batas waktu.</p>","misconceptionId":"mis-bi-fiksi-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>Suara lemari pendingin lenyap, derak air dari talang terdengar, percakapan mengecil, dan cahaya kendaraan sesekali menyapu lantai.</p>"},{"key":"B","text":"<p>Pak Arman memiliki sebuah warung dengan meja yang berada di bagian tengah ruangan.</p>","misconceptionId":"mis-bi-fiksi-004"},{"key":"C","text":"<p>Dua pengendara sebelumnya memilih berteduh di teras warung milik Pak Arman.</p>","misconceptionId":"mis-bi-fiksi-004"},{"key":"D","text":"<p>Seseorang kemudian membagikan roti yang sebelumnya tersimpan di dalam tasnya.</p>","misconceptionId":"mis-bi-fiksi-005"},{"key":"E","text":"<p>Pak Arman adalah pemilik warung yang mengetahui tempat menyimpan lampu darurat.</p>","misconceptionId":"mis-bi-fiksi-001"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-003';
update public.questions set statements = '[{"id":"A","text":"<p>Percakapan orang-orang mendadak mengecil ketika listrik padam.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-fiksi-005"},{"id":"B","text":"<p>Setelah lampu darurat dinyalakan dan situasi ditangani, orang-orang mulai berbicara lagi.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-fiksi-006"},{"id":"C","text":"<p>Nama Pak Arman membuktikan bahwa hujan akan segera berhenti setelah listrik padam.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-fiksi-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>Rafi hampir menolak bantuan, kemudian menerimanya dan mengakui bahwa memaksakan diri dapat memperlambat penyelesaian masalah.</p>"},{"key":"B","text":"<p>Rafi tiba di ujung gang ketika rantai sepedanya lepas dan tangannya kemudian terkena oli.</p>","misconceptionId":"mis-bi-fiksi-007"},{"key":"C","text":"<p>Seorang anak berhenti di dekat Rafi dan menunjuk sebuah rumah yang dicat hijau.</p>","misconceptionId":"mis-bi-fiksi-004"},{"key":"D","text":"<p>Ayah anak itu datang membawa kunci kecil dan memasang kembali rantai sepeda.</p>","misconceptionId":"mis-bi-fiksi-006"},{"key":"E","text":"<p>Rafi membersihkan tangannya menggunakan tisu sebelum melanjutkan perjalanan.</p>","misconceptionId":"mis-bi-fiksi-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>Rafi hampir menjawab tidak ketika anak itu menawarkan bantuan.</p>"},{"key":"B","text":"<p>Ia tidak ingin terlihat tidak bisa memperbaiki sepedanya sendiri.</p>"},{"key":"C","text":"<p>Tangannya menghitam karena terkena oli rantai sepeda.</p>","misconceptionId":"mis-bi-fiksi-007"},{"key":"D","text":"<p>Setelah melihat jam dan rantai yang masih menggantung, Rafi menerima tawaran bantuan.</p>"},{"key":"E","text":"<p>Rumah yang ditunjuk anak itu memiliki cat berwarna hijau.</p>","misconceptionId":"mis-bi-fiksi-004"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>Langit berubah dari kelabu ke biru pucat, bangku masih berembun, kios baru dibuka, dan jalan perlahan mulai ramai.</p>"},{"key":"B","text":"<p>Mira duduk di bangku halte sambil memeluk sebuah map di depan dadanya dan menunggu bus yang akan datang.</p>","misconceptionId":"mis-bi-fiksi-010"},{"key":"C","text":"<p>Bus datang dari arah tikungan sebelum berhenti di dekat halte tempat Mira menunggu.</p>","misconceptionId":"mis-bi-fiksi-004"},{"key":"D","text":"<p>Seorang petugas kebersihan menyapu daun basah menjauh dari tepi jalan.</p>","misconceptionId":"mis-bi-fiksi-004"},{"key":"E","text":"<p>Mira merapikan ujung map sebelum berdiri ketika bus yang ditunggunya terlihat.</p>","misconceptionId":"mis-bi-fiksi-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-007';
update public.questions set statements = '[{"id":"A","text":"<p>Bangku logam masih menyimpan titik-titik embun.</p>","correctCategoryKey":"mendukung","misconceptionId":"mis-bi-fiksi-004"},{"id":"B","text":"<p>Pemilik kios mulai mengangkat pintu gulung ketika jalan perlahan ramai.</p>","correctCategoryKey":"mendukung","misconceptionId":"mis-bi-fiksi-004"},{"id":"C","text":"<p>Mira membawa map, sehingga dapat dipastikan halte itu berada tepat di depan sekolahnya.</p>","correctCategoryKey":"tidak_mendukung","misconceptionId":"mis-bi-fiksi-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Seseorang membagikan roti dari tasnya ketika orang-orang sudah mulai berbicara kembali.</p>"},{"key":"B","text":"<p>Percakapan orang-orang mendadak mengecil sesaat setelah listrik padam.</p>","misconceptionId":"mis-bi-fiksi-010"},{"key":"C","text":"<p>Seorang anak memeluk tas sambil memperhatikan kilat dari balik kaca.</p>","misconceptionId":"mis-bi-fiksi-005"},{"key":"D","text":"<p>Dua pengendara bergeser masuk ketika angin membawa tempias ke teras.</p>","misconceptionId":"mis-bi-fiksi-006"},{"key":"E","text":"<p>Pak Arman meminta orang-orang tidak berdiri dekat pintu untuk sementara.</p>","misconceptionId":"mis-bi-fiksi-003"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Nara bersedia menggunakan waktu yang tersisa untuk memverifikasi data sebelum pengiriman.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-fiksi-010"},{"id":"B","text":"<p>Nara melibatkan Dimas dalam pemeriksaan ulang setelah menemukan dan memperbaiki kesalahan.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-fiksi-010"},{"id":"C","text":"<p>Nara bersikap demikian karena pernah dihukum akibat kesalahan data pada tugas sebelumnya.</p>","correctCategoryKey":"tidak_didukung","misconceptionId":"mis-bi-fiksi-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-fiksi-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>Karena itu, sebelum mengunggah dokumen, pengguna dapat memeriksa apakah setiap data di dalamnya memang diperlukan untuk tujuan yang hendak dicapai.</p>"},{"key":"B","text":"<p>Karena itu, semua dokumen pribadi sebaiknya tidak pernah diproses dengan perangkat digital dalam keadaan apa pun.</p>","misconceptionId":"mis-bi-prediksi-010"},{"key":"C","text":"<p>Selain surat pemesanan, foto makanan dan pemandangan juga sering diunggah pengguna ke berbagai layanan digital.</p>","misconceptionId":"mis-bi-prediksi-006"},{"key":"D","text":"<p>Dengan demikian, kualitas ringkasan terutama ditentukan oleh banyaknya data pribadi yang disertakan dalam dokumen sumber.</p>","misconceptionId":"mis-bi-prediksi-005"},{"key":"E","text":"<p>Pada akhirnya, Rani memutuskan membeli perangkat baru agar dapat menyimpan lebih banyak foto dokumen di rumah.</p>","misconceptionId":"mis-bi-prediksi-001"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>menentukan lebih dahulu informasi apa yang benar-benar dibutuhkan untuk menyelesaikan tugas</p>"},{"key":"B","text":"<p>menghapus atau menutupi data pribadi yang tidak diperlukan sebelum dokumen diunggah</p>"},{"key":"C","text":"<p>mengunggah dokumen secara utuh agar sistem memiliki sebanyak mungkin konteks pribadi</p>","misconceptionId":"mis-bi-prediksi-005"},{"key":"D","text":"<p>menggunakan potongan teks yang relevan jika foto dokumen lengkap tidak diperlukan</p>"},{"key":"E","text":"<p>menganggap seluruh informasi aman dibagikan selama tujuan pengguna hanya meminta ringkasan</p>","misconceptionId":"mis-bi-prediksi-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>Dito dan warga memasang penutup pada rak lalu menata kembali buku yang masih dapat digunakan.</p>"},{"key":"B","text":"<p>Dito membongkar rak dan membawanya jauh dari halte tanpa membicarakannya lagi dengan warga.</p>","misconceptionId":"mis-bi-prediksi-004"},{"key":"C","text":"<p>Para pedagang meminta seluruh buku dibuang karena tidak ada seorang pun yang tertarik membaca.</p>","misconceptionId":"mis-bi-prediksi-005"},{"key":"D","text":"<p>Anak yang membawa buku memutuskan berhenti datang karena rak hanya boleh digunakan orang dewasa.</p>","misconceptionId":"mis-bi-prediksi-001"},{"key":"E","text":"<p>Warga mengganti rak buku dengan papan iklan karena hujan membuktikan kegiatan membaca tidak mungkin dilakukan.</p>","misconceptionId":"mis-bi-prediksi-002"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-003';
update public.questions set statements = '[{"id":"A","text":"<p>Rak tetap dipertahankan dengan perlindungan tambahan karena warga mulai ikut merawatnya.</p>","correctCategoryKey":"masuk_akal","misconceptionId":"mis-bi-prediksi-004"},{"id":"B","text":"<p>Jumlah orang yang terlibat dapat bertambah karena sumbangan buku mulai muncul tanpa diminta secara pribadi.</p>","correctCategoryKey":"masuk_akal","misconceptionId":"mis-bi-prediksi-009"},{"id":"C","text":"<p>Dito menutup rak secara permanen karena sejak awal tidak ada tanda warga tertarik pada keberadaannya.</p>","correctCategoryKey":"tidak_masuk_akal","misconceptionId":"mis-bi-prediksi-004"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>Pengguna dapat mempertahankan notifikasi penting, membatasi yang bersifat informatif, dan menonaktifkan pemberitahuan promosi yang tidak dibutuhkan.</p>"},{"key":"B","text":"<p>Semua aplikasi sebaiknya dihapus karena setiap bentuk notifikasi pada akhirnya selalu mengganggu konsentrasi.</p>","misconceptionId":"mis-bi-prediksi-010"},{"key":"C","text":"<p>Perangkat seluler terus berkembang dari tahun ke tahun dengan ukuran layar dan kapasitas penyimpanan yang berbeda.</p>","misconceptionId":"mis-bi-prediksi-006"},{"key":"D","text":"<p>Notifikasi keamanan sebaiknya diperlakukan sama dengan promosi agar pengguna tidak perlu menentukan prioritas.</p>","misconceptionId":"mis-bi-prediksi-005"},{"key":"E","text":"<p>Masalah notifikasi dapat diselesaikan sepenuhnya dengan meningkatkan kecepatan koneksi internet pada perangkat.</p>","misconceptionId":"mis-bi-prediksi-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>meninjau jenis notifikasi berdasarkan seberapa cepat informasi tersebut perlu ditindaklanjuti</p>"},{"key":"B","text":"<p>membedakan pengaturan untuk pesan keamanan, jadwal, aktivitas sosial, dan promosi</p>"},{"key":"C","text":"<p>menyalakan seluruh notifikasi agar pengguna tidak perlu menentukan mana yang penting</p>","misconceptionId":"mis-bi-prediksi-005"},{"key":"D","text":"<p>menyesuaikan pemberitahuan dengan kebutuhan perhatian, bukan hanya jumlah aplikasi</p>"},{"key":"E","text":"<p>mematikan seluruh pemberitahuan karena semua jenis pesan memiliki tingkat urgensi yang sama</p>","misconceptionId":"mis-bi-prediksi-010"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>Arga memainkan bagian awal perlahan, kemudian mulai menemukan kembali pola permainan yang sebelumnya terasa kaku.</p>"},{"key":"B","text":"<p>Arga langsung memainkan seluruh lagu tanpa kesalahan dan menyatakan kecemasannya telah hilang sepenuhnya.</p>","misconceptionId":"mis-bi-prediksi-008"},{"key":"C","text":"<p>Nisa mengambil gitar dari Arga dan mengumumkan bahwa bagian solo telah diberikan kepada pemain lain.</p>","misconceptionId":"mis-bi-prediksi-004"},{"key":"D","text":"<p>Arga meninggalkan ruang musik tanpa menyelesaikan petikan pertama dan tidak kembali pada hari pentas.</p>","misconceptionId":"mis-bi-prediksi-002"},{"key":"E","text":"<p>Kelompok membatalkan pentas sekolah karena satu anggota keluarga Arga tidak dapat hadir menonton.</p>","misconceptionId":"mis-bi-prediksi-002"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-007';
update public.questions set statements = '[{"id":"A","text":"<p>Arga mungkin kembali mencoba bagian solo setelah tekanan untuk tampil sempurna dikurangi.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-prediksi-004"},{"id":"B","text":"<p>Nisa kemungkinan memberi ruang kepada Arga untuk menentukan kesiapan setelah ia mencoba bermain kembali.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-prediksi-007"},{"id":"C","text":"<p>Arga pasti menjadi penampil terbaik dan tidak lagi merasakan kecemasan ketika pentas berlangsung.</p>","correctCategoryKey":"tidak_didukung","misconceptionId":"mis-bi-prediksi-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Nisa tidak memaksakan keputusan tentang solo dan Arga memulai kembali lagu dengan tempo lebih pelan.</p>"},{"key":"B","text":"<p>Arga selalu datang lebih awal ke ruang musik sejak awal semester sebelum anggota lain tiba.</p>","misconceptionId":"mis-bi-prediksi-004"},{"key":"C","text":"<p>Pentas sekolah dijadwalkan berlangsung tiga hari setelah kesalahan Arga mulai muncul dalam latihan.</p>","misconceptionId":"mis-bi-prediksi-009"},{"key":"D","text":"<p>Ruang musik memiliki jendela yang berada dekat tempat Arga biasanya duduk sebelum latihan dimulai.</p>","misconceptionId":"mis-bi-prediksi-009"},{"key":"E","text":"<p>Kakak Arga sebelumnya selalu datang menyaksikan setiap penampilan yang pernah diikutinya.</p>","misconceptionId":"mis-bi-prediksi-001"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Penulis menjelaskan prinsip membagikan data minimum yang diperlukan untuk suatu tujuan.</p>","correctCategoryKey":"koheren","misconceptionId":"mis-bi-prediksi-003"},{"id":"B","text":"<p>Penulis memberi contoh dokumen lain yang perlu diperiksa sebelum informasi tertentu diunggah.</p>","correctCategoryKey":"koheren","misconceptionId":"mis-bi-prediksi-006"},{"id":"C","text":"<p>Penulis beralih membahas sejarah perkembangan kamera ponsel tanpa menghubungkannya dengan pemilahan data.</p>","correctCategoryKey":"tidak_koheren","misconceptionId":"mis-bi-prediksi-006"}]'::jsonb, updated_at = now() where id = 'tka-bi-prediksi-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>Seorang siswa memilih rute perjalanan yang direkomendasikan aplikasi setelah memeriksa kondisi jalan dan waktu yang tersedia.</p>"},{"key":"B","text":"<p>Seorang siswa menyalin seluruh daftar rekomendasi aplikasi ke buku catatan agar tidak ada satu pun pilihan yang hilang.</p>","misconceptionId":"mis-bi-relevansi-005"},{"key":"C","text":"<p>Seorang siswa membeli barang yang muncul paling atas dalam hasil pencarian karena deskripsinya terlihat paling lengkap.</p>","misconceptionId":"mis-bi-relevansi-001"},{"key":"D","text":"<p>Seorang siswa berhenti menggunakan aplikasi rekomendasi karena pernah menemukan satu pilihan yang tidak sesuai kebutuhannya.</p>","misconceptionId":"mis-bi-relevansi-003"},{"key":"E","text":"<p>Seorang siswa memilih kegiatan yang sama dengan temannya meskipun waktu dan biaya yang mereka miliki berbeda.</p>","misconceptionId":"mis-bi-relevansi-004"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>membandingkan rekomendasi jadwal belajar dari aplikasi dengan waktu kosong yang benar-benar dimiliki</p>"},{"key":"B","text":"<p>memeriksa bahan makanan yang tersedia sebelum mengikuti menu yang disarankan aplikasi</p>"},{"key":"C","text":"<p>menganggap rekomendasi pertama selalu paling tepat karena sistem telah mengurutkannya</p>","misconceptionId":"mis-bi-relevansi-001"},{"key":"D","text":"<p>menilai saran rute berdasarkan kondisi perjalanan sebelum memutuskan mengikutinya</p>"},{"key":"E","text":"<p>menolak seluruh bantuan digital karena keputusan akhir tetap membutuhkan pertimbangan pengguna</p>","misconceptionId":"mis-bi-relevansi-003"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>Panitia kegiatan luar ruang memindahkan sebagian acara ke tempat teduh setelah melihat prakiraan hujan pada jam tertentu.</p>"},{"key":"B","text":"<p>Panitia membatalkan semua kegiatan selama sebulan karena pernah turun hujan pada salah satu hari pelaksanaan.</p>","misconceptionId":"mis-bi-relevansi-003"},{"key":"C","text":"<p>Seorang pengendara tetap melewati jalan tergenang karena pada pagi hari hujan di rumahnya masih ringan.</p>","misconceptionId":"mis-bi-relevansi-004"},{"key":"D","text":"<p>Seorang siswa mengabaikan peringatan cuaca karena kegiatan yang akan diikuti dianggap sangat penting.</p>","misconceptionId":"mis-bi-relevansi-006"},{"key":"E","text":"<p>Panitia mengganti warna poster kegiatan setelah membaca informasi prakiraan cuaca untuk wilayah sekitar.</p>","misconceptionId":"mis-bi-relevansi-009"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-003';
update public.questions set statements = '[{"id":"A","text":"<p>Membawa perlengkapan tambahan setelah mengetahui kondisi yang mungkin mengganggu perjalanan.</p>","correctCategoryKey":"relevan","misconceptionId":"mis-bi-relevansi-005"},{"id":"B","text":"<p>Mengubah waktu keberangkatan setelah informasi terbaru menunjukkan risiko lebih tinggi pada jam tertentu.</p>","correctCategoryKey":"relevan","misconceptionId":"mis-bi-relevansi-004"},{"id":"C","text":"<p>Membatalkan seluruh aktivitas setiap kali terdapat kemungkinan hujan, tanpa mempertimbangkan tingkat risiko.</p>","correctCategoryKey":"tidak_relevan","misconceptionId":"mis-bi-relevansi-003"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>Seseorang menemukan kartu identitas dan menyerahkannya kepada petugas tempat ditemukannya tanpa memotret lalu menyebarkan seluruh datanya.</p>"},{"key":"B","text":"<p>Seseorang membuka percakapan pada ponsel yang ditemukan agar dapat mengetahui sebanyak mungkin tentang pemiliknya.</p>","misconceptionId":"mis-bi-relevansi-008"},{"key":"C","text":"<p>Seseorang mengunggah foto kartu identitas yang ditemukan secara utuh ke media sosial supaya cepat dikenal pemiliknya.</p>","misconceptionId":"mis-bi-relevansi-008"},{"key":"D","text":"<p>Seseorang menyimpan barang temuan selama beberapa minggu karena tidak ingin melibatkan pihak lain dalam proses pengembalian.</p>","misconceptionId":"mis-bi-relevansi-004"},{"key":"E","text":"<p>Seseorang membaca dokumen pribadi dalam tas yang ditemukan karena berniat memastikan barang tersebut benar-benar penting.</p>","misconceptionId":"mis-bi-relevansi-008"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>tujuan mengembalikan barang dapat dicapai tanpa membuka isi komunikasi pribadi</p>"},{"key":"B","text":"<p>Damar menggunakan petunjuk yang tersedia pada bagian luar sebelum mencari data yang lebih sensitif</p>"},{"key":"C","text":"<p>semua barang yang ditemukan harus selalu diserahkan kepada sekolah apa pun tempat penemuannya</p>","misconceptionId":"mis-bi-relevansi-003"},{"key":"D","text":"<p>petugas yang relevan dapat membantu proses pengembalian tanpa Damar perlu mengakses pesan</p>"},{"key":"E","text":"<p>privasi berarti seseorang tidak boleh melihat informasi apa pun yang melekat pada barang temuan</p>","misconceptionId":"mis-bi-relevansi-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>Seorang siswa memeriksa jadwal ujian terbaru sebelum berangkat karena jadwal yang diingatnya berasal dari pengumuman sebelumnya.</p>"},{"key":"B","text":"<p>Seorang siswa menghafalkan seluruh isi pengumuman lama agar tidak perlu membuka informasi terbaru.</p>","misconceptionId":"mis-bi-relevansi-004"},{"key":"C","text":"<p>Seorang pembeli memilih toko yang sama setiap minggu karena sudah mengenal orang yang bekerja di sana.</p>","misconceptionId":"mis-bi-relevansi-001"},{"key":"D","text":"<p>Seorang siswa menyalin jadwal milik temannya tanpa memastikan bahwa kelas mereka memiliki jadwal yang sama.</p>","misconceptionId":"mis-bi-relevansi-010"},{"key":"E","text":"<p>Seorang pelanggan menolak perubahan harga karena jumlah pembelian minggu lalu berbeda dengan hari ini.</p>","misconceptionId":"mis-bi-relevansi-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-007';
update public.questions set statements = '[{"id":"A","text":"<p>Memeriksa kembali tarif terbaru sebelum menghitung biaya layanan yang nilainya dapat berubah.</p>","correctCategoryKey":"sesuai","misconceptionId":"mis-bi-relevansi-002"},{"id":"B","text":"<p>Mengonfirmasi lokasi pertemuan pada pesan terbaru ketika sebelumnya pernah terjadi perubahan tempat.</p>","correctCategoryKey":"sesuai","misconceptionId":"mis-bi-relevansi-002"},{"id":"C","text":"<p>Menganggap informasi lama pasti masih berlaku karena sebelumnya pernah terbukti benar.</p>","correctCategoryKey":"tidak_sesuai","misconceptionId":"mis-bi-relevansi-004"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Memeriksa kembali harga pada foto daftar bulan lalu meskipun tersedia daftar resmi yang baru diperbarui hari ini.</p>"},{"key":"B","text":"<p>Memeriksa pengumuman terbaru sebelum mengisi formulir yang ketentuannya baru saja berubah.</p>","misconceptionId":"mis-bi-relevansi-009"},{"key":"C","text":"<p>Membandingkan jumlah tagihan dengan daftar tarif yang berlaku pada hari transaksi.</p>","misconceptionId":"mis-bi-relevansi-009"},{"key":"D","text":"<p>Mengonfirmasi jadwal pada kanal resmi setelah mendapat kabar bahwa waktunya mungkin berubah.</p>","misconceptionId":"mis-bi-relevansi-002"},{"key":"E","text":"<p>Membaca petunjuk versi terbaru sebelum menggunakan layanan yang prosedurnya baru diperbarui.</p>","misconceptionId":"mis-bi-relevansi-002"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Banyak keputusan sehari-hari melibatkan pilihan yang perlu dibandingkan dengan batas waktu, biaya, atau kebutuhan nyata.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-relevansi-002"},{"id":"B","text":"<p>Saran awal dapat membantu memperluas pilihan tanpa harus dianggap sebagai keputusan akhir.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-relevansi-005"},{"id":"C","text":"<p>Peristiwa itu relevan karena rekomendasi digital selalu lebih akurat daripada pertimbangan manusia.</p>","correctCategoryKey":"tidak_tepat","misconceptionId":"mis-bi-relevansi-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-relevansi-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>haru yang bercampur hangat karena kehilangan fisik diimbangi oleh kenangan yang tetap hidup</p>"},{"key":"B","text":"<p>kemarahan karena tokoh aku menilai rumah lama seharusnya tidak pernah diberikan kepada orang lain</p>","misconceptionId":"mis-bi-emosi-007"},{"key":"C","text":"<p>ketakutan karena aroma masakan membuat tokoh aku merasa masa lalu akan kembali secara nyata</p>","misconceptionId":"mis-bi-emosi-002"},{"key":"D","text":"<p>kegembiraan tanpa kesedihan karena tokoh aku telah sepenuhnya melupakan rumah dan kehidupan lamanya</p>","misconceptionId":"mis-bi-emosi-003"},{"key":"E","text":"<p>kekecewaan kepada tetangga karena kursi dari rumah lama telah diberikan kepadanya</p>","misconceptionId":"mis-bi-emosi-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>kontras antara jendela yang kini gelap dan lampu dapur yang hidup dalam ingatan</p>"},{"key":"B","text":"<p>aroma bawang di minyak panas yang menghidupkan kembali pengalaman masa lalu</p>"},{"key":"C","text":"<p>informasi bahwa kunci rumah disimpan di sebuah laci apartemen</p>","misconceptionId":"mis-bi-emosi-010"},{"key":"D","text":"<p>pernyataan bahwa ada sesuatu yang hilang sekaligus sesuatu yang tetap tinggal</p>"},{"key":"E","text":"<p>penggunaan kata “kotak-kotak” untuk menyebut wadah bekal yang disiapkan pada pagi hari</p>","misconceptionId":"mis-bi-emosi-002"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>baterai hampir habis, sambungan terputus, pesan tidak terkirim, dan akhirnya layar ponsel padam</p>"},{"key":"B","text":"<p>hujan membuat permukaan jalan di depan halte tampak hitam dan terus bergerak</p>","misconceptionId":"mis-bi-emosi-010"},{"key":"C","text":"<p>dua orang yang sebelumnya menunggu memilih pulang menggunakan kendaraan daring</p>","misconceptionId":"mis-bi-emosi-005"},{"key":"D","text":"<p>sebuah truk kecil muncul dari tikungan setelah Lani mendengar suara mesin kendaraan</p>","misconceptionId":"mis-bi-emosi-005"},{"key":"E","text":"<p>papan nomor rute terlihat di balik kaca depan ketika kendaraan berikutnya mendekat</p>","misconceptionId":"mis-bi-emosi-006"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-003';
update public.questions set statements = '[{"id":"A","text":"<p>Ketika ponsel padam dan kendaraan pertama ternyata bukan bus, ketegangan pembaca dapat meningkat.</p>","correctCategoryKey":"sesuai","misconceptionId":"mis-bi-emosi-006"},{"id":"B","text":"<p>Saat nomor rute terlihat dan bus berhenti, respons dapat bergeser dari cemas menuju lega.</p>","correctCategoryKey":"sesuai","misconceptionId":"mis-bi-emosi-008"},{"id":"C","text":"<p>Akhir cerita menunjukkan kemarahan Lani kepada pengemudi karena bus datang terlambat.</p>","correctCategoryKey":"tidak_sesuai","misconceptionId":"mis-bi-emosi-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>dari tegang karena hasil belum jelas menjadi lega ketika nomor Raka akhirnya ditemukan</p>"},{"key":"B","text":"<p>dari bosan karena percakapan berhenti menjadi marah ketika Sinta mendekati papan pengumuman</p>","misconceptionId":"mis-bi-emosi-007"},{"key":"C","text":"<p>dari gembira karena Raka yakin lolos menjadi kecewa setelah ia membaca baris terakhir</p>","misconceptionId":"mis-bi-emosi-009"},{"key":"D","text":"<p>dari takut kepada Sinta menjadi tenang karena Raka akhirnya menerima sebotol air</p>","misconceptionId":"mis-bi-emosi-007"},{"key":"E","text":"<p>dari sedih melihat kursi kosong menjadi bangga karena Raka memilih duduk di kursi nomor tiga</p>","misconceptionId":"mis-bi-emosi-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>Raka melipat kertas terlalu cepat ketika menjawab pertanyaan Sinta.</p>"},{"key":"B","text":"<p>Sinta berhenti dan memeriksa papan sekali lagi sebelum menoleh kepada Raka.</p>"},{"key":"C","text":"<p>Raka mengatakan “Jangan bercanda” setelah Sinta menyebut nomornya ada.</p>"},{"key":"D","text":"<p>Sinta membawa dua botol air ketika memasuki ruang tunggu.</p>","misconceptionId":"mis-bi-emosi-010"},{"key":"E","text":"<p>Raka akhirnya duduk di kursi nomor tiga setelah menerima botol.</p>","misconceptionId":"mis-bi-emosi-006"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>hangat dan optimistis karena kegagalan kecil diikuti kemauan untuk mencoba kembali</p>"},{"key":"B","text":"<p>putus asa karena perahu yang terbalik menunjukkan semua usaha anak akan selalu gagal</p>","misconceptionId":"mis-bi-emosi-004"},{"key":"C","text":"<p>marah kepada pengemudi karena teks menunjukkan mobil sengaja merusak permainan anak</p>","misconceptionId":"mis-bi-emosi-007"},{"key":"D","text":"<p>takut karena matahari yang muncul menandakan genangan akan menjadi semakin berbahaya</p>","misconceptionId":"mis-bi-emosi-002"},{"key":"E","text":"<p>kecewa karena anak meninggalkan perahu pertama tanpa berusaha mengeringkannya lebih dahulu</p>","misconceptionId":"mis-bi-emosi-005"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-007';
update public.questions set statements = '[{"id":"A","text":"<p>Butir air pada daun dan perahu kertas di genangan membantu membangun suasana lembut setelah hujan.</p>","correctCategoryKey":"mendukung","misconceptionId":"mis-bi-emosi-010"},{"id":"B","text":"<p>Tindakan anak mengambil lembar baru dan mulai melipat lagi mendukung rasa optimistis.</p>","correctCategoryKey":"mendukung","misconceptionId":"mis-bi-emosi-004"},{"id":"C","text":"<p>Munculnya matahari membuktikan anak sedang menghadapi ancaman besar yang menimbulkan ketakutan.</p>","correctCategoryKey":"tidak_mendukung","misconceptionId":"mis-bi-emosi-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>bekal disusun dalam kotak-kotak dengan nasi hangat dan telur pada pagi hari</p>"},{"key":"B","text":"<p>jendela rumah yang dahulu bercahaya kini digambarkan dalam keadaan gelap</p>","misconceptionId":"mis-bi-emosi-010"},{"key":"C","text":"<p>aroma masakan membuat dapur kecil seolah menyala kembali dalam ingatan</p>","misconceptionId":"mis-bi-emosi-010"},{"key":"D","text":"<p>kunci rumah lama kini tersimpan di laci apartemen yang jauh</p>","misconceptionId":"mis-bi-emosi-005"},{"key":"E","text":"<p>penutup menyandingkan sesuatu yang telah hilang dengan sesuatu yang tetap tinggal</p>","misconceptionId":"mis-bi-emosi-003"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-009';
update public.questions set statements = '[{"id":"A","text":"<p>Penonton dapat merasakan tegang ketika Sinta berhenti dan memeriksa papan sebelum memberi kepastian.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-emosi-009"},{"id":"B","text":"<p>Tawa pendek Raka setelah menemukan nomornya dapat memperkuat rasa lega setelah ketidakpastian.</p>","correctCategoryKey":"didukung","misconceptionId":"mis-bi-emosi-008"},{"id":"C","text":"<p>Penonton diarahkan membenci panitia karena panitia sengaja menyembunyikan nomor Raka.</p>","correctCategoryKey":"tidak_didukung","misconceptionId":"mis-bi-emosi-007"}]'::jsonb, updated_at = now() where id = 'tka-bi-emosi-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>bergerak bersama </p>"},{"key":"B","text":"<p>melangkah cepat</p>","misconceptionId":"mis-bi-serapan-001"},{"key":"C","text":"<p>beradu cepat</p>","misconceptionId":"mis-bi-serapan-001"},{"key":"D","text":"<p>mengatur bersama</p>","misconceptionId":"mis-bi-serapan-002"},{"key":"E","text":"<p>berpikir bersama</p>","misconceptionId":"mis-bi-serapan-002"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-001';
update public.questions set options = '[{"key":"A","text":"<p>Ancaman plastik terhadap lautan.</p>"},{"key":"B","text":"<p>Efek dari pemanasan laut.</p>","misconceptionId":"mis-bi-inferensi-002"},{"key":"C","text":"<p>Kadar tingkat keasaman laut.</p>","misconceptionId":"mis-bi-inferensi-002"},{"key":"D","text":"<p>Pemompaan CO<sub>2</sub> ke atmosfer.</p>","misconceptionId":"mis-bi-inferensi-001"},{"key":"E","text":"<p>Ancaman bagi negara berkembang.</p>","misconceptionId":"mis-bi-inferensi-003"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-002';
update public.questions set options = '[{"key":"A","text":"<p>Sampah plastik di laut akan lebih banyak daripada jumlah ikan.</p>"},{"key":"B","text":"<p>Lautan akan terus mengalami pemanasan dan semakin asam.</p>","misconceptionId":"mis-bi-hubungan-007"},{"key":"C","text":"<p>Manusia terus memompa lebih banyak CO<sub>2</sub> ke atmosfer.</p>","misconceptionId":"mis-bi-hubungan-007"},{"key":"D","text":"<p>Jumlah ikan yang terancam punah semakin banyak.</p>","misconceptionId":"mis-bi-hubungan-009"},{"key":"E","text":"<p>Penggunaan plastik terus meningkat dan tidak dikelola dengan baik</p>"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-003';
update public.questions set statements = '[{"id":"A","text":"<p>Menginformasikan kepada pembaca bahwa pemecahan masalah sampah merupakan tanggung jawab utama kita sebagai masyarakat sipil sehingga sulit untuk diselesaikan.</p>","correctCategoryKey":"salah","misconceptionId":"mis-bi-inferensi-003"},{"id":"B","text":"<p>Menunjukkan kepada pembaca bahwa permasalahan sampah plastik sangat rumit dan tidak bisa diselesaikan dalam jangka waktu singkat.</p>","correctCategoryKey":"benar","misconceptionId":"mis-bi-hubungan-006"},{"id":"C","text":"<p>Membuktikan kepada pembaca bahwa permasalahan sampah yang rumit disebabkan pemecahan masalah yang bergantung pada perekonomian negara berkembang.</p>","correctCategoryKey":"salah","misconceptionId":"mis-bi-inferensi-003"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-004';
update public.questions set statements = '[{"id":"A","text":"<p>Kekecewaan dan kesedihan tokoh aku terhadap sikap Ayahnya yang tidak mengizinkannya masuk sekolah di musim <em>maddongi, </em>padahal dia harus mempersiapkan diri untuk bersaing dalam lomba dengan siswa sekolah lain.</p>","correctCategoryKey":"benar","misconceptionId":"mis-bi-inferensi-006"},{"id":"B","text":"<p>Kemarahan hati tokoh aku terhadap Ayahnya yang melarang dia pergi sekolah karena sedang musim <em>maddongi </em>di sawah dan dia diberi tugas menghalau burung yang hinggap pada padi di sawah mereka.</p>","correctCategoryKey":"salah","misconceptionId":"mis-bi-inferensi-006"},{"id":"C","text":"<p>Perasaan tertekan tokoh aku terhadap peraturan keluarganya yang mengharuskan dia tidak masuk sekolah setiap musim <em>maddongi, </em>padahal dia ingin sekali belajar dan tidak mau ketinggalan pelajaran.</p>","correctCategoryKey":"salah","misconceptionId":"mis-bi-inferensi-003"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-005';
update public.questions set options = '[{"key":"A","text":"<p><em>Iyye</em> akan datang menasehati Ayah karena melarang tokoh aku untuk belajar.</p>","misconceptionId":"mis-bi-prediksi-001"},{"key":"B","text":"<p>Tokoh aku akan kehilangan kesempatan belajar untuk mengikuti</p>"},{"key":"C","text":"<p>Ayah akan tetap melarang tokoh aku untuk belajar dan mengikuti lomba.</p>","misconceptionId":"mis-bi-prediksi-003"},{"key":"D","text":"<p>Permasalahan tokoh aku dan ayah akan berlarut karena tidak terselesaikan.</p>"},{"key":"E","text":"<p>Tokoh aku tidak akan bisa fokus untuk belajar dan mengikuti lomba yang diadakan sekolah.</p>","misconceptionId":"mis-bi-prediksi-001"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-006';
update public.questions set options = '[{"key":"A","text":"<p>Masih ditemukan orang tua yang tidak memedulikan pendidikan anaknya demi membantu pekerjaan mereka.</p>"},{"key":"B","text":"<p>Terbenturnya cita-cita anak karena tradisi sebuah keluarga yang mengutamakan anak mampu bekerja mandiri.</p>","misconceptionId":"mis-bi-relevansi-002"},{"key":"C","text":"<p>Asumsi bahwa bekerja lebih bermanfaat daripada sekolah yang dianggap tidak menghasilkan apa-apa untuk keluarga.</p>","misconceptionId":"mis-bi-relevansi-006"},{"key":"D","text":"<p>Kebiasaan anak-anak tidak sekolah di musim <em>maddongi </em>demi menjalankan tradisi di lingkungan keluarga mereka.</p>","misconceptionId":"mis-bi-relevansi-001"},{"key":"E","text":"<p>Orang tua mengarahkan anak-anak untuk rajin bekerja membantu mereka di sawah agar bisa melanjutkan kehidupannya kelak.</p>","misconceptionId":"mis-bi-relevansi-002"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-007';
update public.questions set options = '[{"key":"A","text":"<p>Menginformasikan jenis dan rasa makanan yang mengandung Rhodamin B.</p>","misconceptionId":"mis-bi-inferensi-002"},{"key":"B","text":"<p>Menjelaskan dampak penggunaan Rhodamin B pada bahan-bahan industri.</p>","misconceptionId":"mis-bi-inferensi-009"},{"key":"C","text":"<p>Mengimbau agar masyarakat tidak menggunakan barang-barang yang mengandung Rhodamin B.</p>","misconceptionId":"mis-bi-inferensi-003"},{"key":"D","text":"<p>Menginformasikan dampak mengonsumsi makanan yang mengandung Rhodamin B bagi tubuh.</p>"},{"key":"E","text":"<p>Menjelaskan gejala yang timbul akibat mengkonsumsi makanan yang mengandung Rhodamin B.</p>","misconceptionId":"mis-bi-inferensi-002"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-008';
update public.questions set options = '[{"key":"A","text":"<p>Rhodamin B sering disalahgunakan sebagai pewarna makanan karena menawarkan cita rasa yang tinggi.</p>","misconceptionId":"mis-bi-hubungan-007"},{"key":"B","text":"<p>Rhodamin B berdampak buruk bagi kesehatan, tetapi diperlukan pada industri, seperti tekstil dan kertas.</p>"},{"key":"C","text":"<p>Rhodamin B berdampak buruk bagi kesehatan, tetapi mudah ditemukan pada kembang gula dan sirup.</p>","misconceptionId":"mis-bi-inferensi-009"},{"key":"D","text":"<p>Rhodamin B yang berbentuk serbuk kristal dan berwarna hijau digunakan pada industri tekstil dan kertas.</p>","misconceptionId":"mis-bi-hubungan-009"},{"key":"E","text":"<p>Rhodamin B berdampak buruk bagi kesehatan, meskipun dampak itu baru terlihat beberapa tahun kemudian.</p>","misconceptionId":"mis-bi-evalinfo-007"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-009';
update public.questions set options = '[{"key":"A","text":"<p>Mendorong masyarakat untuk menghindari Rhodamin B dalam berbagai keperluan.</p>","misconceptionId":"mis-bi-evalinfo-007"},{"key":"B","text":"<p>Meningkatkan kesadaran masyarakat tentang bahaya Rhodamin B dalam makanan</p>"},{"key":"C","text":"<p>Menunjukkan bahwa Rhodamin B aman digunakan dalam industri tekstil dan kertas.</p>","misconceptionId":"mis-bi-inferensi-009"},{"key":"D","text":"<p>Menjelaskan bahwa Rhodamin B adalah zat berbahaya jika dikonsumsi, terutama dalam jangka panjang.</p>"},{"key":"E","text":"<p>Memperingatkan masyarakat agar menghindari makanan berwarna mencolok yang berisiko mengandung Rhodamin B.</p>"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-010';
update public.questions set statements = '[{"id":"A","text":"<p>Paragraf pertama (1) menggunakan pola sebab-akibat karena menjelaskan bagaimana teknologi digital menyebabkan perubahan bagi UKM.</p>","correctCategoryKey":"benar","misconceptionId":"mis-bi-hubungan-001"},{"id":"B","text":"<p>Paragraf kedua (2) menggunakan pola proses karena menjelaskan langkah-langkah bagaimana UKM memanfaatkan <em>e-commerce</em>.</p>","correctCategoryKey":"benar","misconceptionId":"mis-bi-kerangka-003"},{"id":"C","text":"<p>Paragraf ketiga (3) menggunakan pola klasifikasi karena membagi sistem pembayaran UKM menjadi beberapa kategori yang berbeda.</p>","correctCategoryKey":"salah","misconceptionId":"mis-bi-kerangka-002"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-012';
update public.questions set statements = '[{"id":"A","text":"<p>Sena menyoroti bahwa teks harus mudah dipahami oleh semua kalangan, termasuk yang awam terhadap ekonomi.</p>","correctCategoryKey":"tidak-setuju","misconceptionId":"mis-bi-evalinfo-005"},{"id":"B","text":"<p>Sena mempertimbangkan kelengkapan dan dasar bukti dari informasi yang merupakan bagian dari menilai keakuratan teks.</p>","correctCategoryKey":"setuju","misconceptionId":"mis-bi-evalinfo-004"},{"id":"C","text":"<p>Sena memiliki inisiatif untuk memperbaiki isi teks dengan pendapat pribadinya sebagai ahli ekonomi agar lebih informatif.</p>","correctCategoryKey":"tidak-setuju","misconceptionId":"mis-bi-evalinfo-010"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-013';
update public.questions set options = '[{"key":"A","text":"<p>Peristiwa pindahan yang sering dialami pegawai suatu instansi untuk kepentingan promosi jabatan.</p>","misconceptionId":"mis-bi-serapan-004"},{"key":"B","text":"<p>Peristiwa pindah rumah dari kampung halaman ke tempat yang jauh untuk jangka waktu lama.</p>","misconceptionId":"mis-bi-serapan-009"},{"key":"C","text":"<p>Pindah rumah bersama seluruh anggota keluarga dengan membawa semua barang rumah tangga.</p>"},{"key":"D","text":"<p>Pindah rumah untuk mengikuti tugas kedinasan orang tua di tempat baru yang letaknya sangat jauh.</p>","misconceptionId":"mis-bi-serapan-004"},{"key":"E","text":"<p>Kegiatan pindah rumah untuk sementara waktu dan akan berpindah lagi ke rumah dinas yang lain.</p>","misconceptionId":"mis-bi-serapan-010"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-014';
update public.questions set statements = '[{"id":"A","text":"<p>Sahabat tokoh saya masih memiliki seragam pramuka untuk dipakai.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-prediksi-007"},{"id":"B","text":"<p>Punggung sahabat tokoh saya tidak akan memiliki luka bakar.</p>","correctCategoryKey":"tidak-tepat","misconceptionId":"mis-bi-prediksi-009"},{"id":"C","text":"<p>Sahabat tokoh saya akan mencari jangkrik tanpa perlu berlari.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-prediksi-007"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-015';
update public.questions set options = '[{"key":"A","text":"<p>Saya langsung menyatakan ingin ikut, tapi dia keberatan.</p>","misconceptionId":"mis-bi-fiksi-003"},{"key":"B","text":"<p>Dia memang tidak memiliki banyak pakaian hingga seragam sekolah biasa dipakai kapan saja.</p>","misconceptionId":"mis-bi-fiksi-004"},{"key":"C","text":"<p>Sahabat saya itu tanggap melingkupi tubuh saya dengan seragam coklatnya.</p>"},{"key":"D","text":"<p>Dia menggendong saya lalu berlari sembari membujuk-bujuk saya untuk tetap tenang.</p>"},{"key":"E","text":"<p>Rasa tanggung jawab yang besar seperti memberinya kekuatan berlipat untuk tetap bersama saya.</p>"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-016';
update public.questions set statements = '[{"id":"A","text":"<p>Kata “deforestasi” pada kalimat (2) paragraf kedua.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-serapan-008"},{"id":"B","text":"<p>Kata “menginvestigasi” pada kalimat (2) paragraf ketiga.</p>","correctCategoryKey":"tidak-tepat","misconceptionId":"mis-bi-serapan-007"},{"id":"C","text":"<p>Kata “polusi” pada kalimat (1) paragraf keempat.</p>","correctCategoryKey":"tepat","misconceptionId":"mis-bi-serapan-002"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-017';
update public.questions set options = '[{"key":"A","text":"<p>Akibat-sebab yang diperkuat dengan contoh deforestasi dan kerusakan lingkungan</p>","misconceptionId":"mis-bi-kerangka-004"},{"key":"B","text":"<p>Sebab-akibat yang mengajak pembaca untuk mengambil langkah tegas</p>"},{"key":"C","text":"<p>Penegasan yang diperinci dengan contoh konkret yang bisa diaplikasikan pembaca</p>","misconceptionId":"mis-bi-hubungan-002"},{"key":"D","text":"<p>Perbandingan dari dua pandangan terkait dampak negatif deforestasi</p>","misconceptionId":"mis-bi-hubungan-009"},{"key":"E","text":"<p>Penyimpulan bahwa teknologi hijau merupakan solusi masalah deforestasi</p>","misconceptionId":"mis-bi-inferensi-003"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-018';
update public.questions set options = '[{"key":"A","text":"<p>Pada sisi lain, teknologi hijau memunculkan deforestasi dan polusi.</p>","misconceptionId":"mis-bi-prediksi-005"},{"key":"B","text":"<p>Sehingga dampak negatif lingkungan berdampak pula pada kualitas hidup.</p>","misconceptionId":"mis-bi-prediksi-003"},{"key":"C","text":"<p>Di samping itu, teknologi hijau dapat menciptakan dunia yang lebih baik untuk generasi yang akan datang.</p>"},{"key":"D","text":"<p>Di samping itu, bumi yang menggunakan teknologi hijau akan semakin menghadapi tantangan besar.</p>","misconceptionId":"mis-bi-prediksi-005"},{"key":"E","text":"<p>Jadi, teknologi hijau berperan dalam menghilangnya keanekaragaman hayati.</p>","misconceptionId":"mis-bi-prediksi-007"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-019';
update public.questions set options = '[{"key":"A","text":"<p>Teknologi hijau merupakan inovasi yang dirancang untuk mengatasi berbagai tantangan lingkungan global, terutama terkait dengan perubahan iklim.</p>"},{"key":"B","text":"<p>Perubahan iklim, yang dipicu oleh peningkatan emisi gas rumah kaca akibat aktivitas manusia, menyebabkan cuaca ekstrem, suhu global menurun, dan naiknya permukaan air laut.</p>","misconceptionId":"mis-bi-evalinfo-002"},{"key":"C","text":"<p>Teknologi hijau seperti energi terbarukan (tenaga surya, angin) dapat mengurangi ketergantungan pada bahan bakar fosil.</p>"},{"key":"D","text":"<p>Teknologi hijau juga sangat penting dalam upaya adaptasi terhadap dampak perubahan teknologi yang sudah tidak bisa dihindari.</p>","misconceptionId":"mis-bi-evalinfo-005"},{"key":"E","text":"<p>Melalui teknologi hijau, kita dapat mengurangi dampak negatif terhadap lingkungan dan memperbaiki kualitas hidup.</p>"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-indonesia-sma-020';

commit;
